window.SAT_DATA = window.SAT_DATA || {};
(window.SAT_DATA.vocabQuestions = window.SAT_DATA.vocabQuestions || []).push(
{"id": "vq-hd-alga", "wordId": "hd-alga", "skill": "words-in-context", "stem": "Peering through his microscope at a drop of pond water, the student identified a single-celled ______: a simple, non-flowering organism that, much like the seaweeds it faintly resembled, harnessed sunlight to manufacture its own food.", "choices": [{"text": "fungus", "why": "A fungus absorbs nutrients from other matter and does not photosynthesize, contradicting 'harnessed sunlight to manufacture its own food.'", "tag": "unsupported"}, {"text": "bacterium", "why": "A bacterium is single-celled but is not a plantlike organism resembling seaweed, which the passage stresses.", "tag": "unsupported"}, {"text": "alga", "why": "The colon defines it as a simple, non-flowering, sunlight-harnessing organism resembling seaweed—precisely an alga."}, {"text": "mineral", "why": "A mineral is a nonliving inorganic substance, so it cannot be a single-celled organism that resembles seaweed and makes food.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-animosities-toward", "wordId": "hd-animosities-toward", "skill": "words-in-context", "stem": "Decades after the border war finally ended, the two mountain villages remained bitterly unreconciled: the deep ______ the other, nursed through generations of remembered wrongs, resurfaced the moment the disputed valley was so much as mentioned.", "choices": [{"text": "affinities toward", "why": "Reversed: affinities are feelings of warm attraction, contradicting 'bitterly unreconciled' and 'remembered wrongs.'", "tag": "reversed"}, {"text": "sympathies toward", "why": "Reversed: sympathies are feelings of compassion or alliance, the opposite of the hostility the passage describes.", "tag": "reversed"}, {"text": "suspicions toward", "why": "Suspicions are wary distrust, milder than the deep, active hostility that 'resurfaced' over remembered wrongs.", "tag": "too-specific"}, {"text": "animosities toward", "why": "'Bitterly unreconciled,' 'remembered wrongs,' and feelings that 'resurfaced' mark deep hostile feelings directed at the other village."}], "answer": 3},
{"id": "vq-hd-anomaly", "wordId": "hd-anomaly", "skill": "words-in-context", "stem": "Most of the survey's data points clustered neatly along the predicted curve, but one stubborn measurement stood far apart from the rest, a puzzling ______ the astronomers could not dismiss and that ultimately betrayed the presence of an undiscovered planet.", "choices": [{"text": "coincidence", "why": "A coincidence is a chance co-occurrence, but the passage treats the odd point as a meaningful deviation, not an accident.", "tag": "unsupported"}, {"text": "precedent", "why": "A precedent is an earlier case used as a model, irrelevant to a lone measurement that departs from the pattern.", "tag": "unsupported"}, {"text": "anomaly", "why": "A measurement that 'stood far apart from the rest' of a neat pattern is a deviation from what was expected—an outlier."}, {"text": "norm", "why": "Reversed: a norm is the usual standard, the opposite of a point standing far apart from the rest.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-antecedent", "wordId": "hd-antecedent", "skill": "words-in-context", "stem": "Legal historians regard the medieval guild not as a mere curiosity but as a direct ______ of the modern trade union: centuries before industrialization, guilds already negotiated wages, regulated training, and shielded members from arbitrary dismissal.", "choices": [{"text": "antecedent", "why": "The colon explains that guilds performed union-like functions 'centuries before industrialization,' so the blank must name a thing that existed earlier and prefigured what came later."}, {"text": "successor", "why": "Reversed: a successor comes after what it replaces, but the passage states that guilds preceded trade unions by centuries.", "tag": "reversed"}, {"text": "byproduct", "why": "Reversed: a byproduct is something produced incidentally by another thing, which would make the guild an outgrowth of the union rather than its forerunner.", "tag": "reversed"}, {"text": "counterpart", "why": "A counterpart is a parallel equivalent existing alongside something else; nothing in the passage suggests guilds and unions coexisted—one preceded the other.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-approbation", "wordId": "hd-approbation", "skill": "words-in-context", "stem": "When Alfred Wegener first proposed continental drift, geologists ridiculed the idea; only decades later, once studies of seafloor spreading supplied a plausible mechanism, did the theory finally win the ______ of the scientific establishment.", "choices": [{"text": "derision", "why": "Reversed: derision means mocking scorn—the initial reaction the sentence explicitly contrasts with what the theory 'finally' won.", "tag": "reversed"}, {"text": "notoriety", "why": "Notoriety is fame for something bad; the arc of the sentence moves from ridicule toward acceptance, not toward disrepute.", "tag": "reversed"}, {"text": "approbation", "why": "The contrast between early ridicule and what the theory later 'won' requires a word meaning approval or praise—approbation."}, {"text": "scrutiny", "why": "Scrutiny is close, neutral examination; the theory had been examined all along, and 'win' signals a favorable verdict, not mere attention.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-appropriate", "wordId": "hd-appropriate", "skill": "words-in-context", "stem": "Statisticians warn that no test is universally valid: a technique ______ for large, normally distributed samples can produce badly misleading conclusions when researchers use it on the small, skewed data sets common in field ecology.", "choices": [{"text": "obligatory", "why": "Too strong: obligatory means required by rule, but the passage claims only that the technique suits certain data, not that anyone must use it.", "tag": "too-broad"}, {"text": "detrimental", "why": "Reversed: detrimental means harmful, yet the technique works well for large samples and misleads only when transferred to the wrong data.", "tag": "reversed"}, {"text": "arbitrary", "why": "Arbitrary means chosen at random without reason; the passage describes a principled match between technique and sample type, not a random one.", "tag": "unsupported"}, {"text": "appropriate", "why": "The contrast—valid for one kind of sample, misleading for another—turns on suitability, so the blank must mean fitting for a particular situation."}], "answer": 3},
{"id": "vq-hd-approximate", "wordId": "hd-approximate", "skill": "words-in-context", "stem": "With no complete census surviving from the fourteenth century, historians can only ______ the population of medieval London, piecing together tax rolls, parish registers, and grain-import records to arrive at a defensible range rather than a firm count.", "choices": [{"text": "approximate", "why": "The phrase 'a defensible range rather than a firm count' signals an estimate close to but not exactly the true figure—the meaning of approximate."}, {"text": "verify", "why": "To verify is to confirm as exactly true, but with no census surviving there is no precise figure to confirm—only fragmentary evidence to estimate from.", "tag": "unsupported"}, {"text": "tabulate", "why": "Too exact: tabulating implies counting items precisely into totals, which 'range rather than a firm count' explicitly rules out.", "tag": "too-specific"}, {"text": "exaggerate", "why": "To exaggerate is to overstate deliberately; the historians aim at a 'defensible' figure, the opposite of inflating it.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-connoisseur", "wordId": "hd-connoisseur", "skill": "words-in-context", "stem": "Museums frequently consult her before any major acquisition: decades spent studying brushwork, varnish, and pigment have made her a genuine ______, able to tell a master's own hand from a skilled imitation at a single glance.", "choices": [{"text": "novice", "why": "A novice is an inexperienced beginner, the opposite of someone with decades of expert judgment.", "tag": "reversed"}, {"text": "custodian", "why": "A custodian is a caretaker of property, not necessarily an expert judge of artistic quality.", "tag": "unsupported"}, {"text": "patron", "why": "A patron financially supports the arts, which is unrelated to the discerning taste the passage emphasizes.", "tag": "true-but-irrelevant"}, {"text": "connoisseur", "why": "'Decades studying pigment' and telling a master from an imitation define an expert judge in matters of taste."}], "answer": 3},
{"id": "vq-hd-consistent-with", "wordId": "hd-consistent-with", "skill": "words-in-context", "stem": "The pathologist stopped short of asserting certainty, observing only that the pattern of injuries was ______ a fall from a great height: nothing in the physical evidence contradicted that explanation, and every fracture matched the distribution such a fall would produce.", "choices": [{"text": "at odds with", "why": "'At odds with' means in conflict, but the evidence is said to contradict nothing about the fall.", "tag": "reversed"}, {"text": "consistent with", "why": "'Nothing contradicted that explanation' and 'every fracture matched' show the injuries were in agreement or harmony with a fall."}, {"text": "irrelevant to", "why": "'Irrelevant to' means unrelated, yet the injuries directly support the fall theory.", "tag": "unsupported"}, {"text": "responsible for", "why": "'Responsible for' reverses the causal direction; the fall caused the injuries, not the other way around.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-conspicuous", "wordId": "hd-conspicuous", "skill": "words-in-context", "stem": "The male bird's plumage is anything but subtle; set against the muted green of the canopy, its scarlet crest is so ______ that predators and potential mates alike can pick the bird out from a considerable distance.", "choices": [{"text": "drab", "why": "Drab means dull and unnoticeable, the opposite of a scarlet crest visible from far away.", "tag": "reversed"}, {"text": "fleeting", "why": "Fleeting refers to brief duration, but the passage concerns how visible the crest is, not how long it lasts.", "tag": "unsupported"}, {"text": "conspicuous", "why": "'Spot it from a considerable distance' and 'anything but subtle' define the blank as clearly visible."}, {"text": "fragile", "why": "Fragile means easily broken, which is irrelevant to how easily the crest is seen.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-commiserate", "wordId": "hd-commiserate", "skill": "words-in-context", "stem": "When the youngest members of the crew returned from the failed expedition, the veteran sailors did not lecture or celebrate; instead they gathered quietly around the fire to ______ with them, sharing in the disappointment of a voyage that had cost so much and yielded so little.", "choices": [{"text": "gloat", "why": "Gloat means to take smug pleasure in misfortune, but the veterans respond with fellow feeling, not triumph.", "tag": "reversed"}, {"text": "commiserate", "why": "'Sharing in the disappointment' after a painful failure signals expressing sympathy together, which is what commiserate means."}, {"text": "reminisce", "why": "Reminisce means to recall the past fondly; the sailors are sharing sorrow over a recent loss, not fondly recollecting memories.", "tag": "unsupported"}, {"text": "rejoice", "why": "Rejoice means to feel great joy, the opposite of the sorrow the passage describes ('cost so much and yielded so little').", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-committed", "wordId": "hd-committed", "skill": "words-in-context", "stem": "Throughout decades of setbacks, arrests, and public ridicule, the reformer never wavered in her campaign for voting rights; colleagues described her as utterly ______ to the cause, willing to sacrifice comfort and reputation for a goal she might not live to see achieved.", "choices": [{"text": "indifferent", "why": "Indifferent means showing no interest, but she sacrificed comfort and reputation for the cause.", "tag": "reversed"}, {"text": "ambivalent", "why": "Ambivalent means having mixed or conflicting feelings, yet the passage says she 'never wavered.'", "tag": "reversed"}, {"text": "committed", "why": "'Never wavered' and 'willing to sacrifice comfort and reputation' point directly to being dedicated and devoted to a cause, the meaning of committed."}, {"text": "obstinate", "why": "Obstinate means stubbornly refusing to change one's mind, implying an unreasonableness the passage does not support; it praises devotion, not intransigence.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-commonality", "wordId": "hd-commonality", "skill": "words-in-context", "stem": "Although the two languages developed on opposite sides of the ocean and share no recent history, linguists were struck by a surprising ______: both organize their verbs according to nearly identical patterns, a resemblance that hints at deeper principles underlying human grammar.", "choices": [{"text": "disparity", "why": "Disparity means a marked difference, but the passage stresses that the two languages share nearly identical patterns.", "tag": "reversed"}, {"text": "correlation", "why": "Correlation names a statistical association between varying quantities, but the passage describes a shared structural feature, not co-varying measurements.", "tag": "too-specific"}, {"text": "anomaly", "why": "An anomaly is a deviation from the norm, whereas the passage highlights a feature the two languages have in common.", "tag": "too-specific"}, {"text": "commonality", "why": "The colon elaborates that 'both organize their verbs according to nearly identical patterns'—a shared feature, which is precisely a commonality."}], "answer": 3},
{"id": "vq-hd-commonplace", "wordId": "hd-commonplace", "skill": "words-in-context", "stem": "Only a generation ago, carrying a device that could reach the entire internet from one's pocket seemed the stuff of science fiction; today such technology is so ______ that commuters scarcely glance at the small screens glowing in every hand around them.", "choices": [{"text": "commonplace", "why": "'In every hand' and 'scarcely glance' show the technology is now ordinary through sheer frequency, which is what commonplace means."}, {"text": "novel", "why": "Novel means new and unusual, but the passage contrasts the once-futuristic device with its present ordinariness.", "tag": "reversed"}, {"text": "mundane", "why": "Mundane stresses dullness or tedium, whereas the passage emphasizes how widespread the technology has become, not that it is boring.", "tag": "too-specific"}, {"text": "extravagant", "why": "Extravagant means lavish or excessive, but the passage says nothing about cost or excess.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-communities-with", "wordId": "hd-communities-with", "skill": "words-in-context", "stem": "Epidemiologists studying longevity have concentrated on the so-called Blue Zones — ______ a strikingly large share of residents older than one hundred — hoping to isolate the dietary and social habits that these long-lived populations share.", "choices": [{"text": "populations without", "why": "'Without' negates the very abundance of centenarians that defines a Blue Zone.", "tag": "reversed"}, {"text": "communities with", "why": "Blue Zones are groups defined by possessing a shared trait—a high proportion of centenarians—and 'with' marks that shared characteristic."}, {"text": "individuals with", "why": "A single individual cannot contain a 'share of residents'; the passage describes whole groups, not persons.", "tag": "too-specific"}, {"text": "regions beyond", "why": "'Beyond' places something past the trait rather than possessing it, describing no shared characteristic.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-complementary", "wordId": "hd-complementary", "skill": "words-in-context", "stem": "Critics praised the film's score not because it drew attention to itself but because it was so ______ to the images on screen: the swelling strings deepened each emotional beat, and the silences let the visuals speak, so that music and picture strengthened one another.", "choices": [{"text": "extraneous", "why": "Extraneous means irrelevant or superfluous, but the score is integral and enhancing.", "tag": "reversed"}, {"text": "complementary", "why": "'Music and picture strengthened one another' describes two elements enhancing each other's qualities, the meaning of complementary."}, {"text": "subordinate", "why": "Subordinate stresses being merely secondary or inferior, emphasizing hierarchy rather than the mutual enhancement the passage describes.", "tag": "too-specific"}, {"text": "identical", "why": "Identical means exactly alike, but the passage describes two different elements reinforcing each other, not sameness.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-compliance-with", "wordId": "hd-compliance-with", "skill": "words-in-context", "stem": "The audit found that the factory's safety record had improved dramatically after new management took over, largely because of its strict ______ the international regulations governing hazardous materials, rules that earlier supervisors had routinely ignored.", "choices": [{"text": "resistance to", "why": "Resistance means active opposition, but the improved record came from obeying the rules, not fighting them.", "tag": "reversed"}, {"text": "indifference to", "why": "Indifference is a lack of concern—precisely the attitude of the earlier supervisors who 'ignored' the rules, not the new management being credited.", "tag": "reversed"}, {"text": "compliance with", "why": "'Strict' adherence to regulations, contrasted with supervisors who 'ignored' them, is exactly compliance with a standard."}, {"text": "awareness of", "why": "Awareness means merely knowing the regulations, but the passage credits actually conforming to them for the improvement.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-hd-concealed", "wordId": "hd-concealed", "skill": "words-in-context", "stem": "When conservators examined the old portrait with infrared imaging, they discovered an entirely different composition ______ beneath the visible paint: the artist had abandoned an earlier scene and painted directly over it, hiding the first work for centuries.", "choices": [{"text": "displayed", "why": "Displayed means openly shown, but the earlier composition was hidden under the surface layer.", "tag": "reversed"}, {"text": "concealed", "why": "'Hiding the first work for centuries' beneath the visible paint means it was kept out of sight—the meaning of concealed."}, {"text": "eclipsed", "why": "Eclipsed means overshadowed or surpassed in prominence, which concerns relative importance rather than being physically hidden from view.", "tag": "too-broad"}, {"text": "embellished", "why": "Embellished means decorated or adorned, but nothing suggests the hidden scene was ornamented; it was simply painted over.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-contrived", "wordId": "hd-contrived", "skill": "words-in-context", "stem": "Reviewers of the young playwright's debut praised its ambition but faulted its dialogue: at every emotional peak the characters delivered speeches that seemed engineered to manufacture feeling rather than to arise naturally from the situation, leaving even sympathetic critics convinced the drama was ______.", "choices": [{"text": "contrived", "why": "The clue 'engineered to manufacture feeling rather than to arise naturally' defines something artificial and forced."}, {"text": "formulaic", "why": "Means predictable or following a set pattern; the passage faults forced artificiality, not conventionality.", "tag": "unsupported"}, {"text": "spontaneous", "why": "Means arising naturally and unplanned, the exact opposite of the manufactured quality described.", "tag": "reversed"}, {"text": "understated", "why": "Means restrained or subtle; nothing concerns restraint, only over-engineered emotion.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-cordially", "wordId": "hd-cordially", "skill": "words-in-context", "stem": "Although the two ambassadors represented empires that had warred for a generation, they greeted each other ______ at the summit, exchanging warm compliments and genuine courtesies that startled the journalists who had expected open hostility.", "choices": [{"text": "brusquely", "why": "Means in an abrupt, curt manner, the opposite of the warmth described.", "tag": "reversed"}, {"text": "cordially", "why": "'Warm compliments and genuine courtesies' specify a friendly, gracious manner."}, {"text": "formally", "why": "Means in a proper, ceremonious way, which need not be warm or friendly and misses the affection shown.", "tag": "too-broad"}, {"text": "warily", "why": "Means in a guarded, distrustful manner, contradicting the genuine friendliness on display.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-corroboration", "wordId": "hd-corroboration", "skill": "words-in-context", "stem": "The historian's bold claim rested at first on a single diary, and skeptics dismissed it; only when customs ledgers and a ship's manifest independently recorded the same voyage did her thesis gain the ______ it needed to persuade the field.", "choices": [{"text": "refutation", "why": "Means evidence that disproves a claim, the opposite of the support the thesis gained.", "tag": "reversed"}, {"text": "speculation", "why": "Means conjecture without evidence, whereas the passage supplies concrete independent records.", "tag": "unsupported"}, {"text": "corroboration", "why": "Independent ledgers and a manifest 'recorded the same voyage,' confirming the claim with additional evidence."}, {"text": "embellishment", "why": "Means the addition of invented or decorative detail, not the factual confirmation the thesis received.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-counterintuitive", "wordId": "hd-counterintuitive", "skill": "words-in-context", "stem": "The result was thoroughly documented and has since been replicated many times, yet it remains ______: adding a slower lane to the congested highway actually reduced everyone's travel time, an outcome that flatly contradicts what most drivers assume must be true.", "choices": [{"text": "self-evident", "why": "Means obvious without proof, the opposite of a finding that defies expectation.", "tag": "reversed"}, {"text": "counterintuitive", "why": "An outcome that 'flatly contradicts what most drivers assume' is contrary to common-sense expectation."}, {"text": "paradoxical", "why": "Implies an internal self-contradiction, but the finding is consistent and well-supported, merely surprising.", "tag": "too-specific"}, {"text": "conventional", "why": "Means conforming to ordinary expectation, the opposite of what the passage describes.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-criteria-for", "wordId": "hd-criteria-for", "skill": "words-in-context", "stem": "Before reviewing a single submission, the grant panel published the ______ funding: a clear list of the standards, weighted by importance, against which the scientific merit of each proposal would be judged and ranked.", "choices": [{"text": "criteria for", "why": "'A clear list of the standards ... against which the scientific merit of each proposal would be judged and ranked' defines evaluative criteria."}, {"text": "prerequisites for", "why": "Names conditions required to be eligible, not the graded standards used to rank comparative merit.", "tag": "too-specific"}, {"text": "exceptions to", "why": "Names cases exempt from a rule, unrelated to the standards of evaluation described.", "tag": "unsupported"}, {"text": "alternatives to", "why": "Names substitutes or other options, not the measures used to judge proposals.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-deceptive", "wordId": "hd-deceptive", "skill": "words-in-context", "stem": "The anglerfish's glowing lure is remarkably ______: what appears to a small fish to be an easy meal is in fact bait dangling in front of a hidden predator that waits patiently to strike.", "choices": [{"text": "conspicuous", "why": "Too broad: conspicuous merely means highly visible and misses the passage's emphasis on a false impression.", "tag": "too-broad"}, {"text": "deceptive", "why": "'What appears... is in fact bait' signals a false impression, exactly what deceptive names."}, {"text": "luminous", "why": "True but irrelevant: luminous describes the lure's glow but not the trickery the sentence stresses.", "tag": "true-but-irrelevant"}, {"text": "ephemeral", "why": "Unsupported: ephemeral means short-lived, and nothing in the passage concerns duration.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-depleted", "wordId": "hd-depleted", "skill": "words-in-context", "stem": "After decades of intensive mining, the region's once-rich copper reserves were nearly ______: so much ore had been extracted that only trace amounts remained, and the exhausted pits were finally abandoned.", "choices": [{"text": "replenished", "why": "Reversed: replenished means refilled or restored, contradicting 'only trace amounts remained.'", "tag": "reversed"}, {"text": "depleted", "why": "'So much ore had been extracted that only trace amounts remained' defines being used up."}, {"text": "contaminated", "why": "Unsupported: contaminated means polluted, but the passage concerns quantity, not purity.", "tag": "unsupported"}, {"text": "surveyed", "why": "Unsupported: surveyed means examined or mapped, unrelated to reserves running out.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-described", "wordId": "hd-described", "skill": "words-in-context", "stem": "In her field journals, the naturalist carefully ______ each unfamiliar species she encountered, setting down in precise prose the color, size, and behavior of animals that no European had recorded before.", "choices": [{"text": "concealed", "why": "Reversed: concealed means hid, opposite of setting the details down in prose.", "tag": "reversed"}, {"text": "domesticated", "why": "Unsupported: domesticated means tamed, unrelated to recording species in writing.", "tag": "unsupported"}, {"text": "ignored", "why": "Reversed: ignored means disregarded, contradicting careful recording.", "tag": "reversed"}, {"text": "described", "why": "'Setting down in precise prose the color, size, and behavior' matches described, giving a verbal account."}], "answer": 3},
{"id": "vq-hd-developed", "wordId": "hd-developed", "skill": "words-in-context", "stem": "Over many successive generations the isolated island finches gradually ______ beaks of markedly different shapes, each one suited to the particular seeds, insects, and fruits available in its own corner of the archipelago.", "choices": [{"text": "abandoned", "why": "Gave up or discarded; the finches gained specialized beaks over time rather than losing them.", "tag": "reversed"}, {"text": "developed", "why": "'Over many successive generations' and 'gradually... markedly different shapes' signal traits that progressed and advanced over time."}, {"text": "inherited", "why": "Received unchanged from ancestors; but the passage stresses gradual change across generations, not a static trait passed down intact.", "tag": "too-specific"}, {"text": "concealed", "why": "Hid from view; nothing suggests the beaks were hidden, only that their shapes changed.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-discernible", "wordId": "hd-discernible", "skill": "words-in-context", "stem": "Through the modest backyard telescope the distant galaxy appeared only as a faint gray smudge, its delicate spiral arms barely ______ against the dark sky even on the clearest and most favorable viewing nights.", "choices": [{"text": "conspicuous", "why": "Highly visible and obvious—the opposite of arms that are only 'barely' seen.", "tag": "reversed"}, {"text": "colossal", "why": "Enormous in size; this describes magnitude, not whether something can be perceived.", "tag": "unsupported"}, {"text": "discernible", "why": "A 'faint gray smudge' whose arms are 'barely ___ against the dark sky' means they can only just be perceived."}, {"text": "measurable", "why": "Able to be quantified; but the passage is about whether the arms can be seen at all, not measured.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-discourage", "wordId": "hd-discourage", "skill": "words-in-context", "stem": "The city sharply raised the tolls on its central bridge specifically to ______ downtown driving, hoping that the added expense would nudge more weekday commuters onto the newly expanded subway line instead.", "choices": [{"text": "discourage", "why": "Making driving more costly so commuters shift to the subway is meant to reduce or dissuade that behavior."}, {"text": "promote", "why": "To actively encourage; this reverses the intent, since the city wants less downtown driving, not more.", "tag": "reversed"}, {"text": "streamline", "why": "To make a process more efficient; a toll does not smooth out driving, and nothing supports this sense.", "tag": "unsupported"}, {"text": "outlaw", "why": "To ban by law; but a toll raises the cost of driving rather than prohibiting it outright.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-hd-disengage", "wordId": "hd-disengage", "skill": "words-in-context", "stem": "Therapists often advise that in the heat of an argument it is far wiser to briefly ______ from the conversation—stepping away to cool down—than to keep pressing a point that only inflames the other person's anger.", "choices": [{"text": "profit", "why": "To gain advantage from something; nothing in the passage concerns benefit, only stepping back.", "tag": "unsupported"}, {"text": "recoil", "why": "To spring back in fear or disgust; but the advice describes a calm, deliberate pause, not a startled reaction.", "tag": "too-specific"}, {"text": "abstain", "why": "To refrain from something on principle; the point is a temporary withdrawal, not principled avoidance.", "tag": "unsupported"}, {"text": "disengage", "why": "'Stepping away to cool down' rather than pressing on is exactly withdrawing or detaching oneself from the interaction."}], "answer": 3},
{"id": "vq-hd-diverge", "wordId": "hd-diverge", "skill": "words-in-context", "stem": "For the first several chapters the two biographers present nearly identical accounts of the composer's childhood, but their narratives ______ sharply once they reach the disputed question of who financed his early studies.", "choices": [{"text": "converge", "why": "Converge means to come together toward a single point, the opposite of the splitting the contrast 'but... sharply' demands.", "tag": "reversed"}, {"text": "diverge", "why": "The shift from 'nearly identical accounts' to disagreement over a 'disputed question' shows the narratives branch apart, which is what diverge means."}, {"text": "digress", "why": "Digress means to wander off the main topic; it describes a single speaker straying, not two accounts differing from each other.", "tag": "unsupported"}, {"text": "coincide", "why": "Coincide means to agree or occur together, which contradicts the passage's move from agreement to sharp disagreement.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-diverse", "wordId": "hd-diverse", "skill": "words-in-context", "stem": "A single hectare of tropical rainforest can shelter a strikingly ______ community of organisms, containing more species of trees, insects, and birds than are found across the whole of some temperate nations.", "choices": [{"text": "uniform", "why": "Uniform means unvarying and all alike, the opposite of a community holding many different species.", "tag": "reversed"}, {"text": "fragile", "why": "Fragile means easily damaged; rainforests are indeed fragile, but the blank is defined by variety of species, not delicacy.", "tag": "true-but-irrelevant"}, {"text": "diverse", "why": "The clue 'more species of trees, insects, and birds' emphasizes variety of kinds, precisely what diverse means."}, {"text": "abundant", "why": "Abundant means present in great quantity; it is tempting but describes sheer number, whereas the clue stresses the range of different species.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-hd-dogmatic", "wordId": "hd-dogmatic", "skill": "words-in-context", "stem": "The philosophy seminar prized open debate, so students grew frustrated with one classmate whose ______ pronouncements admitted no possibility of error and dismissed every counterargument before it could even be voiced.", "choices": [{"text": "tentative", "why": "Tentative means hesitant and uncertain, the opposite of statements that admit no possibility of error.", "tag": "reversed"}, {"text": "dogmatic", "why": "The details that the pronouncements 'admitted no possibility of error' and dismissed all counterarguments describe stubborn, closed-minded assertion, the meaning of dogmatic."}, {"text": "assertive", "why": "Assertive means confident and forceful in expressing views; it is tempting but lacks the arrogant refusal to consider other perspectives that the passage stresses.", "tag": "too-broad"}, {"text": "impartial", "why": "Impartial means unbiased and open to all sides, contradicting a classmate who rejects every counterargument.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-dramaturge", "wordId": "hd-dramaturge", "skill": "words-in-context", "stem": "Before rehearsals began, the theater company hired a ______ to research the play's historical setting, trim its unwieldy script, and advise the director on which passages would resonate with a contemporary audience.", "choices": [{"text": "dramaturge", "why": "The duties of researching the setting, editing the script, and advising the director on staging define a dramaturge, the theatrical expert on a play's text and production."}, {"text": "playwright", "why": "A playwright is the author who writes an original play; the passage describes editing and advising on an existing script for a production, not composing it.", "tag": "too-specific"}, {"text": "understudy", "why": "An understudy is an actor prepared to substitute for another in performance, not a specialist who researches and revises the script.", "tag": "unsupported"}, {"text": "patron", "why": "A patron is a financial backer of the arts; nothing in the passage concerns funding rather than script expertise.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-disorienting", "wordId": "hd-disorienting", "skill": "words-in-context", "stem": "Visitors to the mirrored gallery often describe the experience as deeply ______: the endless reflections erase any sense of where the walls actually begin, leaving even seasoned museumgoers turning in circles, unsure which way leads back to the exit.", "choices": [{"text": "disorienting", "why": "The clues 'erase any sense of where the walls begin' and 'unsure which way leads back' describe a loss of one's bearings, the meaning of disorienting."}, {"text": "illuminating", "why": "Reversed: illuminating means clarifying or enlightening, the opposite of the confusion the mirrors create.", "tag": "reversed"}, {"text": "immersive", "why": "True but irrelevant: immersive means absorbing and enveloping, which the gallery may be, but it says nothing about losing one's sense of direction.", "tag": "true-but-irrelevant"}, {"text": "monotonous", "why": "Unsupported: monotonous means tediously repetitive, but nothing suggests the experience is dull.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-disparate", "wordId": "hd-disparate", "skill": "words-in-context", "stem": "The accuracy of modern climate models depends on weaving together strikingly ______ streams of evidence, including ice-core samples, satellite images, ocean-buoy readings, and tree-ring records, and fusing these unlike sources into one coherent simulation of the planet's past.", "choices": [{"text": "uniform", "why": "Reversed: uniform means consistent and alike, but the passage lists sources that differ fundamentally in kind.", "tag": "reversed"}, {"text": "voluminous", "why": "True but irrelevant: voluminous means large in quantity, which may describe the data's bulk, but the sentence stresses how unlike the sources are, not how much data there is.", "tag": "true-but-irrelevant"}, {"text": "disparate", "why": "The list of very different evidence types plus 'these unlike sources' signals data that is distinct and dissimilar in nature, the meaning of disparate."}, {"text": "identical", "why": "Reversed: identical means exactly the same, but ice cores, satellites, buoys, and tree rings are anything but the same.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-dispersed", "wordId": "hd-dispersed", "skill": "words-in-context", "stem": "By the time the autumn gusts died down, the dandelion's tiny seeds had been ______ across the entire meadow, carried so far on the wind that scarcely any of them settled anywhere near the plant that had produced them.", "choices": [{"text": "dispersed", "why": "The clues 'across the entire meadow' and 'carried so far... scarcely any settled near the plant' describe seeds scattered widely, which is what dispersed means."}, {"text": "concentrated", "why": "Reversed: concentrated means gathered densely in one place, the opposite of seeds flung across the whole meadow.", "tag": "reversed"}, {"text": "deposited", "why": "Too specific: deposited means set down in a particular spot, but the passage stresses wide scattering, not settling in one location.", "tag": "too-specific"}, {"text": "cultivated", "why": "Wrong domain: cultivated means deliberately grown or tended, but wind-blown seeds were spread by chance, not cultivated.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-dissolution", "wordId": "hd-dissolution", "skill": "words-in-context", "stem": "After months of legislative gridlock had paralyzed the government, the king ordered the ______ of parliament, formally sending every representative home, terminating the body entirely, and calling for fresh elections to be held the following spring.", "choices": [{"text": "ratification", "why": "Unsupported: ratification means formal approval of an agreement, but the passage describes ending a body, not approving one.", "tag": "unsupported"}, {"text": "dissolution", "why": "The clues 'sending every representative home, terminating the body entirely' and calling fresh elections describe the formal ending of an official assembly, which is what dissolution means."}, {"text": "adjournment", "why": "Too specific: adjournment is a temporary suspension of a session, but the king permanently terminated parliament and called new elections.", "tag": "too-specific"}, {"text": "convening", "why": "Reversed: convening means assembling a body together, the opposite of disbanding it.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-ephemeral", "wordId": "hd-ephemeral", "skill": "words-in-context", "stem": "Environmental artist Andy Goldsworthy builds his sculptures from ice, leaves, and blown petals precisely because such works are ______: most dissolve, scatter, or melt within hours of completion, surviving only in photographs.", "choices": [{"text": "ephemeral", "why": "The colon introduces the elaboration 'dissolve, scatter, or melt within hours,' so the blank must mean lasting a very short time."}, {"text": "enduring", "why": "Enduring means lasting a long time — the direct opposite of works that vanish within hours.", "tag": "reversed"}, {"text": "sporadic", "why": "Sporadic means occurring irregularly or infrequently; the passage concerns how long the works last, not how often they appear.", "tag": "unsupported"}, {"text": "monumental", "why": "Monumental describes something massive and built to last; sculptures that melt in hours are the reverse of permanent monuments.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-epitomize", "wordId": "hd-epitomize", "skill": "words-in-context", "stem": "Historians argue that the Crystal Palace, erected for the Great Exhibition of 1851, came to ______ Victorian faith in industrial progress: its vast iron-and-glass frame displayed the era's confidence in engineering more completely than any other structure.", "choices": [{"text": "contradict", "why": "To contradict is to assert the opposite; the building displayed the era's confidence rather than opposing it.", "tag": "reversed"}, {"text": "epitomize", "why": "The colon's claim that the building displayed the era's confidence 'more completely than any other structure' means it was the perfect example of that faith — exactly what epitomize means."}, {"text": "exaggerate", "why": "To exaggerate is to overstate or distort beyond the truth; the passage says the structure faithfully expressed the era's faith, not that it inflated it.", "tag": "too-broad"}, {"text": "commemorate", "why": "To commemorate is to honor the memory of something past; Victorian faith in progress was a living attitude, not a bygone event being memorialized.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-exacerbate", "wordId": "hd-exacerbate", "skill": "words-in-context", "stem": "Hydrologists warned that diverting the river for irrigation would ______ the region's water crisis rather than relieve it, deepening shortages downstream even as upstream fields temporarily flourished.", "choices": [{"text": "exacerbate", "why": "The contrast 'rather than relieve it' plus 'deepening shortages' shows the diversion makes the crisis worse — exactly what exacerbate means."}, {"text": "alleviate", "why": "Alleviate means to ease or relieve, the very outcome the sentence explicitly rules out with 'rather than relieve it.'", "tag": "reversed"}, {"text": "prolong", "why": "Prolong means only to extend something's duration; 'deepening shortages' indicates growing severity, not merely a longer timeline.", "tag": "too-specific"}, {"text": "forestall", "why": "Forestall means to prevent something before it happens; the crisis already exists and the diversion intensifies it.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-enchantment", "wordId": "hd-enchantment", "skill": "words-in-context", "stem": "As the aurora rippled in green sheets across the polar sky, the exhausted researchers forgot their frostbitten fingers entirely, watching in silent ______ as the lights folded and unfurled overhead.", "choices": [{"text": "enchantment", "why": "The researchers forget their pain and watch the lights in rapt silence, a scene of delight and wonder—enchantment."}, {"text": "trepidation", "why": "Trepidation is fearful anxiety; the passage conveys pleasure, not dread.", "tag": "reversed"}, {"text": "indifference", "why": "Indifference is a lack of interest, contradicting their transfixed, absorbed watching.", "tag": "reversed"}, {"text": "bewilderment", "why": "Bewilderment is confusion; the researchers are captivated, not puzzled, by the aurora.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-encourage", "wordId": "hd-encourage", "skill": "words-in-context", "stem": "Rather than penalizing students for wrong answers, the new teaching method is designed to ______ intellectual risk-taking: pupils earn recognition simply for proposing bold hypotheses, whether or not those guesses ultimately prove correct.", "choices": [{"text": "stifle", "why": "Stifle means to suppress or smother; the method rewards risk-taking rather than shutting it down.", "tag": "reversed"}, {"text": "mandate", "why": "Mandate means to command by rule; the method offers recognition and support, not compulsion, and bold guessing cannot simply be ordered.", "tag": "unsupported"}, {"text": "encourage", "why": "Pupils earn recognition for bold hypotheses regardless of correctness, a system built to inspire and support risk-taking—encourage."}, {"text": "deter", "why": "Deter means to discourage, the opposite of fostering risk-taking.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-entrenching", "wordId": "hd-entrenching", "skill": "words-in-context", "stem": "Critics argue that gerrymandered districts do more than tilt a single election; by locking incumbents into safe seats term after term, they risk ______ the very power imbalances that fair maps are meant to dismantle.", "choices": [{"text": "eroding", "why": "Eroding means gradually wearing away, the opposite of locking power imbalances firmly in place.", "tag": "reversed"}, {"text": "exposing", "why": "Exposing means revealing; the districts reinforce the imbalances rather than merely bringing them to light.", "tag": "unsupported"}, {"text": "acknowledging", "why": "Acknowledging means admitting something is so; the passage describes cementing imbalances, not conceding them.", "tag": "unsupported"}, {"text": "entrenching", "why": "By locking incumbents into safe seats term after term, gerrymandering solidifies power imbalances so they resist change—entrenching."}], "answer": 3},
{"id": "vq-hd-expenditure", "wordId": "hd-expenditure", "skill": "words-in-context", "stem": "Economists reviewing the province's finances observed that its total ______ had risen sharply over the decade: new highways, hospitals, and pension programs all drained the treasury faster than tax revenue could replenish it.", "choices": [{"text": "taxation", "why": "Refers to money collected by the government, but the colon lists funds being drained out, not gathered in.", "tag": "reversed"}, {"text": "expenditure", "why": "The colon elaborates money flowing out on highways, hospitals, and pensions, so the blank names the total amount the government spends."}, {"text": "windfall", "why": "Means a sudden, unexpected monetary gain; nothing suggests surprise income, and it is money in rather than out.", "tag": "unsupported"}, {"text": "expense", "why": "Names a single cost item, but the word 'total' and the summed list call for the aggregate amount spent, not one charge.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-hd-exposure-to", "wordId": "hd-exposure-to", "skill": "words-in-context", "stem": "Public-health researchers tracking the factory town's rising asthma rates concluded that prolonged ______ airborne industrial particulates, rather than any inherited predisposition, best accounted for why children there fell ill far more often than those in neighboring communities.", "choices": [{"text": "immunity to", "why": "Means protection against harm, the opposite of the harmful contact that raises illness rates.", "tag": "reversed"}, {"text": "resistance to", "why": "Means the ability to withstand something, contradicting the passage's link between the particulates and rising sickness.", "tag": "reversed"}, {"text": "proximity to", "why": "Means spatial nearness, but being near particulates is not the same as being subjected to and inhaling them over time.", "tag": "too-specific"}, {"text": "exposure to", "why": "The illness caused by prolonged contact with harmful particulates is exactly what exposure to denotes."}], "answer": 3},
{"id": "vq-hd-foretells", "wordId": "hd-foretells", "skill": "words-in-context", "stem": "In many of Shakespeare's tragedies, an ominous natural sign, a sudden storm, an eclipse, or a horse breaking loose, ______ the calamity to come, warning the audience of disaster well before the characters themselves sense that anything is wrong.", "choices": [{"text": "obscures", "why": "Means to hide or make unclear, but the sign reveals rather than conceals the coming disaster.", "tag": "reversed"}, {"text": "recounts", "why": "Means to narrate a past event, but the sign points forward to a calamity that has not yet happened.", "tag": "unsupported"}, {"text": "mourns", "why": "Means to grieve, a reaction to loss that does not match a sign pointing to future disaster.", "tag": "unsupported"}, {"text": "foretells", "why": "A sign that warns 'of disaster well before' it happens predicts the future, the meaning of foretells."}], "answer": 3},
{"id": "vq-hd-forfeiture-of", "wordId": "hd-forfeiture-of", "skill": "words-in-context", "stem": "Under the terms of the medieval charter, a baron who broke his sworn oath to the crown faced a distinctive penalty: not imprisonment or a fine, but the ______ his ancestral lands, which were to be surrendered permanently to the king as punishment for disloyalty.", "choices": [{"text": "acquisition of", "why": "Reversed: to acquire is to gain possession, but the disloyal baron loses his lands rather than obtaining new ones.", "tag": "reversed"}, {"text": "preservation of", "why": "Reversed: to preserve is to protect and keep, the opposite of surrendering the estate to the king as punishment.", "tag": "reversed"}, {"text": "forfeiture of", "why": "The colon and 'surrendered permanently ... as punishment' define losing something as a penalty, which is precisely a forfeiture of the lands.", "tag": ""}, {"text": "distribution of", "why": "Out of scope: to distribute is to share out among many; the passage describes losing the estate as a penalty, not allocating it.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-foster", "wordId": "hd-foster", "skill": "words-in-context", "stem": "The new mentorship program was designed not merely to permit creativity among young engineers but actively to ______ it, pairing novices with veterans who deliberately encouraged experimentation and rewarded original ideas at every stage.", "choices": [{"text": "suppress", "why": "Reversed: to suppress is to hold back or crush, the opposite of encouraging creativity to develop.", "tag": "reversed"}, {"text": "foster", "why": "The contrast 'not merely to permit ... but actively to' plus 'encouraged experimentation and rewarded' signals promoting growth, which is what to foster means.", "tag": ""}, {"text": "regulate", "why": "Out of scope: to regulate is to impose control or rules, not to promote the development of creativity.", "tag": "unsupported"}, {"text": "tolerate", "why": "Too weak: to tolerate is to passively allow, but the stem explicitly rejects mere permitting in favor of active encouragement.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-hd-germination", "wordId": "hd-germination", "skill": "words-in-context", "stem": "Botanists studying desert flora discovered that certain seeds remain inert for years until a rare heavy rainfall triggers ______: only when the soil is thoroughly soaked does the embryo within each seed break through its coat and begin to sprout.", "choices": [{"text": "dormancy", "why": "Reversed: dormancy is a state of inactivity or rest, the opposite of a seed beginning to grow.", "tag": "reversed"}, {"text": "pollination", "why": "Wrong domain: pollination is the transfer of pollen between flowers, not a seed sprouting from the soil.", "tag": "unsupported"}, {"text": "germination", "why": "'The embryo within each seed break through its coat and begin to sprout' describes precisely the seed starting to grow, which is germination.", "tag": ""}, {"text": "maturation", "why": "Wrong stage: maturation is the later process of becoming fully grown, not the initial sprouting the passage describes.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-hegemony", "wordId": "hd-hegemony", "skill": "words-in-context", "stem": "For nearly a century after the war, no rival could challenge the empire's ______ over the region: its fleet controlled every major port, its currency dominated trade, and smaller states quietly shaped their policies around its wishes.", "choices": [{"text": "autonomy", "why": "Reversed: autonomy means self-government or independence, not control exercised over other states.", "tag": "reversed"}, {"text": "sovereignty", "why": "Too specific: sovereignty is supreme authority over one's own territory, whereas the passage describes dominance imposed over other states.", "tag": "too-specific"}, {"text": "hegemony", "why": "'Smaller states shaped their policies around its wishes' and total control of ports and trade describe one power's dominance over others, which is hegemony.", "tag": ""}, {"text": "neutrality", "why": "Reversed: neutrality means refusing to take sides, the opposite of dominating an entire region.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-hierarchy", "wordId": "hd-hierarchy", "skill": "words-in-context", "stem": "In many corporate structures, employees are arranged in a strict ______: each level of authority reports upward to the one above it, and decisions flow downward from the executives at the top to the workers below.", "choices": [{"text": "hierarchy", "why": "The colon introduces an elaboration of ranked levels 'reporting upward' and decisions flowing 'downward,' so the blank must name a system arranged by importance."}, {"text": "consensus", "why": "A consensus is a general agreement reached by a group; nothing in the passage describes shared agreement rather than ranked levels of authority.", "tag": "unsupported"}, {"text": "equilibrium", "why": "An equilibrium is a state of balance among equal forces, the opposite of the unequal top-to-bottom ordering the passage lays out.", "tag": "reversed"}, {"text": "bureaucracy", "why": "A bureaucracy is the apparatus of administrative officials and rules; it is tempting in tone but denotes the machinery of administration, not the ranked ordering of importance described here.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-hd-hypothesis", "wordId": "hd-hypothesis", "skill": "words-in-context", "stem": "Before conducting a single experiment, the biologist formulated a tentative ______ to account for the birds' unusual migration pattern—a provisional explanation that she fully expected to test, and possibly discard, once the field data began to arrive.", "choices": [{"text": "verdict", "why": "A verdict is a final, settled judgment, which contradicts the passage's emphasis on something tentative and open to being discarded.", "tag": "reversed"}, {"text": "axiom", "why": "An axiom is a self-evident truth accepted without proof; the passage instead describes a provisional claim awaiting testing.", "tag": "reversed"}, {"text": "corollary", "why": "A corollary is a proposition that follows from one already proven, but nothing here is derived from a prior established result.", "tag": "unsupported"}, {"text": "hypothesis", "why": "The appositive 'a provisional explanation that she expected to test, and possibly discard' matches a proposed explanation used as a starting point for investigation."}], "answer": 3},
{"id": "vq-hd-illustrated", "wordId": "hd-illustrated", "skill": "words-in-context", "stem": "Rather than relying on abstract definitions alone, the professor ______ the concept of exponential growth with a vivid diagram and a familiar example of doubling bacteria, making the once-confusing idea immediately clear to her students.", "choices": [{"text": "obscured", "why": "Obscured means made unclear or hidden, the opposite of the clarification the diagram and example produce.", "tag": "reversed"}, {"text": "contested", "why": "Contested means disputed or challenged, but nothing in the passage suggests the concept is being argued against.", "tag": "unsupported"}, {"text": "abridged", "why": "Abridged means shortened or condensed; the passage is about clarifying with visuals, not cutting the material's length.", "tag": "unsupported"}, {"text": "illustrated", "why": "The phrase 'with a vivid diagram and a familiar example... immediately clear' matches clarifying an idea through examples and visual aids."}], "answer": 3},
{"id": "vq-hd-immature", "wordId": "hd-immature", "skill": "words-in-context", "stem": "The marine biologist explained that the specimens hauled up in the net were still ______: their reproductive organs had not yet formed, their coloration remained pale and undefined, and none had reached the size typical of the adult population.", "choices": [{"text": "resilient", "why": "Resilient means able to recover quickly from difficulty; nothing in the passage concerns recovery or toughness.", "tag": "unsupported"}, {"text": "immature", "why": "The details that reproductive organs 'had not yet formed' and none 'had reached adult size' directly describe organisms not fully developed."}, {"text": "senescent", "why": "Senescent means aging or deteriorating with age, the opposite of specimens that have not yet finished developing.", "tag": "reversed"}, {"text": "dormant", "why": "Dormant means temporarily inactive; it hints at a not-yet-active state but says nothing about incomplete physical development.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-immersive", "wordId": "hd-immersive", "skill": "words-in-context", "stem": "The museum's new exhibit was designed to be thoroughly ______: visitors donned headsets that surrounded them with the sights and sounds of an ancient marketplace, so completely absorbing that many forgot they were standing in a gallery at all.", "choices": [{"text": "cursory", "why": "Cursory means hasty and superficial, the opposite of the deep, enveloping engagement the exhibit provides.", "tag": "reversed"}, {"text": "austere", "why": "Austere means plain, severe, or stripped down; nothing in the passage suggests severity or simplicity.", "tag": "unsupported"}, {"text": "immersive", "why": "The description of visitors 'surrounded' by sights and sounds and 'so completely absorbing that many forgot' where they stood defines deep absorption."}, {"text": "didactic", "why": "Didactic means intended to instruct or moralize; it tempts as a museum term but describes a teaching purpose, not the enveloping sensory absorption emphasized here.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-impractical", "wordId": "hd-impractical", "skill": "words-in-context", "stem": "Nineteenth-century inventors imagined pneumatic tube networks whisking mail beneath entire cities, but the scheme proved ______: no manufacturing process of the era could produce airtight tubing in the necessary lengths, and excavating beneath crowded streets was prohibitively expensive.", "choices": [{"text": "impractical", "why": "The colon explains the verdict — the tubing could not be manufactured and the excavation was prohibitively expensive — so the blank must mean not feasible to carry out."}, {"text": "ingenious", "why": "True but irrelevant: the idea may well have been clever, but the clues after the colon explain why the scheme failed, not why it was admired.", "tag": "true-but-irrelevant"}, {"text": "inefficient", "why": "Too narrow: inefficient implies a working system that wastes resources, but the passage says the network could not be built at all.", "tag": "too-specific"}, {"text": "obsolete", "why": "Obsolete means outdated and superseded; a system that never existed cannot have been rendered out of date, and no replacement technology is mentioned.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-inadvertently", "wordId": "hd-inadvertently", "skill": "words-in-context", "stem": "While cleaning a newly unearthed Roman mosaic, nineteenth-century excavators ______ destroyed the very artifact they hoped to preserve: the solvents they carefully brushed across the tiles dissolved the ancient adhesive holding the tesserae in place.", "choices": [{"text": "deliberately", "why": "Reversed: deliberately means on purpose, but destroying 'the very artifact they hoped to preserve' shows the outcome ran directly against their intention.", "tag": "reversed"}, {"text": "reluctantly", "why": "Reluctantly implies they knew the harm and proceeded unwillingly, but the passage shows they were unaware the solvents would dissolve the adhesive.", "tag": "unsupported"}, {"text": "inadvertently", "why": "The paradox — destroying what 'they hoped to preserve' while cleaning it — is resolved only by an adverb meaning unintentionally; the damage was an accident of their preservation effort."}, {"text": "carelessly", "why": "Too narrow: carelessly blames negligence, but the passage says the solvents were 'carefully brushed' — the excavators were diligent; the harm was simply unforeseen.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-inconclusive", "wordId": "hd-inconclusive", "skill": "words-in-context", "stem": "Despite enrolling more than four thousand participants, the decade-long trial yielded results physicians could only call ______: patients receiving the therapy fared slightly better, yet the margin was so narrow that chance could not be ruled out, leaving the treatment's value unresolved.", "choices": [{"text": "definitive", "why": "Reversed: definitive means settling the question decisively, but the passage says the treatment's value was left 'unresolved.'", "tag": "reversed"}, {"text": "inconclusive", "why": "The colon supplies the clue — a margin so narrow that 'chance could not be ruled out,' leaving the question 'unresolved' — so the blank must mean failing to yield a definite outcome."}, {"text": "contradictory", "why": "Too narrow: contradictory requires findings that clash with one another, but here the data all point weakly in a single direction — they are indecisive, not conflicting.", "tag": "too-specific"}, {"text": "fabricated", "why": "Fabricated means invented or falsified; nothing in the passage questions the honesty of the trial, only the strength of its outcome.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-inconspicuousness", "wordId": "hd-inconspicuousness", "skill": "words-in-context", "stem": "The peppered moth owes its survival less to speed than to ______: its mottled gray wings so closely match the lichen-crusted bark on which it rests that hunting birds routinely pass over it.", "choices": [{"text": "prominence", "why": "Reversed: prominence means standing out and being easily seen, but the moth survives precisely because predators 'routinely pass over it.'", "tag": "reversed"}, {"text": "agility", "why": "True but irrelevant: the contrast 'less to speed than to' explicitly sets movement-based traits like agility aside in favor of something else.", "tag": "true-but-irrelevant"}, {"text": "subtlety", "why": "Too general: subtlety means understatement or fine nuance broadly, while the clue requires the specific quality of being hard to see against the bark.", "tag": "too-broad"}, {"text": "inconspicuousness", "why": "The colon explains the blank — wings that match the bark so closely that birds 'pass over it' — naming the quality of not being easily seen, i.e., inconspicuousness."}], "answer": 3},
{"id": "vq-hd-independent-of", "wordId": "hd-independent-of", "skill": "words-in-context", "stem": "The researchers designed the trial so that participants' recovery rates would be ______ the placebo effect: a double-blind protocol ensured that expectations about the treatment could not distort the physiological outcomes being recorded.", "choices": [{"text": "contingent on", "why": "Contingent on means dependent upon, the reverse of what the design achieves, since the protocol was meant to remove that influence.", "tag": "reversed"}, {"text": "independent of", "why": "The passage explains that expectations 'could not distort the physiological outcomes,' so the recovery rates must operate separately from, or unaffected by, the placebo effect."}, {"text": "derived from", "why": "Derived from implies the rates originate in the placebo effect, the opposite of the intended separation.", "tag": "reversed"}, {"text": "proportional to", "why": "Proportional to asserts a scaling relationship the passage never establishes; the point is the absence of any influence.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-inevitable", "wordId": "hd-inevitable", "skill": "words-in-context", "stem": "Given the relentless rate at which the glacier was retreating, geologists regarded the valley's eventual flooding as ______: the only open question, they insisted, was not whether the meltwater would inundate the lowlands but precisely when.", "choices": [{"text": "preventable", "why": "Preventable means capable of being stopped, contradicting geologists who treat the flooding as a matter of when, not whether.", "tag": "reversed"}, {"text": "inevitable", "why": "The insistence that the only question is 'not whether but when' establishes the flooding as certain to happen and unavoidable."}, {"text": "hypothetical", "why": "Hypothetical means merely supposed and uncertain, but the passage presents the flooding as a settled certainty.", "tag": "reversed"}, {"text": "imperceptible", "why": "Imperceptible means too slight to notice, unrelated to whether an event will occur.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-inexplicable", "wordId": "hd-inexplicable", "skill": "words-in-context", "stem": "For nearly a decade the periodic dimming of the distant star remained ______: it matched no known pattern of orbiting planets or stellar pulsation, and every model the astronomers constructed failed to account for the strange signal.", "choices": [{"text": "predictable", "why": "Predictable means able to be anticipated, the reverse of a signal no model could account for.", "tag": "reversed"}, {"text": "negligible", "why": "Negligible means too small to matter, but the astronomers treated the strange signal as important enough to model repeatedly.", "tag": "unsupported"}, {"text": "inexplicable", "why": "That 'every model failed to account for' the dimming and it 'matched no known pattern' shows the blank means impossible to explain or understand."}, {"text": "routine", "why": "Routine means ordinary and expected, contradicting a phenomenon described as strange and unmatched by any pattern.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-influx", "wordId": "hd-influx", "skill": "words-in-context", "stem": "The discovery of gold in the region triggered a sudden ______ of prospectors: within a single year the sleepy trading post swelled into a crowded boomtown, its streets thronged with newcomers who arrived by the thousands.", "choices": [{"text": "exodus", "why": "An exodus is a mass departure, the reverse of a town swelling with arriving newcomers.", "tag": "reversed"}, {"text": "scarcity", "why": "Scarcity means a shortage, contradicting streets thronged with thousands of people.", "tag": "reversed"}, {"text": "surplus", "why": "Surplus refers to an excess amount left over, not the arrival or entry of people into a place.", "tag": "unsupported"}, {"text": "influx", "why": "The trading post 'thronged with newcomers arriving by the thousands' shows the blank means an arrival or entry of large numbers of people."}], "answer": 3},
{"id": "vq-hd-innocuous", "wordId": "hd-innocuous", "skill": "words-in-context", "stem": "Gardeners often recoil from the milk snake because of its vivid red-and-black bands, yet the reptile is entirely ______: it carries no venom whatsoever and feeds only on small rodents, posing no danger to the people who encounter it.", "choices": [{"text": "venomous", "why": "'Venomous' directly contradicts the statement that the snake 'carries no venom whatsoever.'", "tag": "reversed"}, {"text": "innocuous", "why": "The details that it 'carries no venom' and poses 'no danger' establish that the snake is harmless."}, {"text": "elusive", "why": "'Elusive' means hard to find or catch; the passage addresses the snake's threat level, not how difficult it is to locate.", "tag": "unsupported"}, {"text": "invasive", "why": "'Invasive' describes a species that spreads aggressively into new habitats, a claim the passage never makes.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-insulation", "wordId": "hd-insulation", "skill": "words-in-context", "stem": "To slash the building's heating and cooling costs, the architects packed the walls with thick layers of ______; the dense material trapped warm air indoors through the winter and blocked the summer heat from seeping in.", "choices": [{"text": "ventilation", "why": "'Ventilation' promotes the flow of air, the opposite of a material meant to trap warm air and block heat.", "tag": "reversed"}, {"text": "insulation", "why": "A dense material that 'trapped warm air' and 'blocked the summer heat' is doing exactly what insulation does."}, {"text": "reinforcement", "why": "'Reinforcement' strengthens a structure mechanically; the passage concerns temperature control, not structural support.", "tag": "unsupported"}, {"text": "ornamentation", "why": "'Ornamentation' is decorative detail, irrelevant to the thermal function described.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-interjected", "wordId": "hd-interjected", "skill": "words-in-context", "stem": "The panel had drifted into comfortable, unanimous agreement when a young scholar abruptly ______, shattering the calm with a sharp objection that none of the seasoned experts had seen coming.", "choices": [{"text": "interjected", "why": "Speaking up 'abruptly' and 'shattering the calm' of an ongoing discussion is exactly interrupting or breaking in."}, {"text": "acquiesced", "why": "'Acquiesced' means agreed without protest, the reverse of a scholar who raised a sharp objection.", "tag": "reversed"}, {"text": "digressed", "why": "'Digressed' means to wander off topic while still speaking; here a new speaker cut into the discussion rather than straying from a subject.", "tag": "unsupported"}, {"text": "withdrew", "why": "'Withdrew' means retreated or pulled back, the opposite of the scholar's forceful entry into the debate.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-intersect", "wordId": "hd-intersect", "skill": "words-in-context", "stem": "The researcher's work sits where two disciplines ______: her studies of migratory birds draw equally on climate science and on economics, meeting precisely at the question of how shifting weather patterns reshape regional food markets.", "choices": [{"text": "diverge", "why": "'Diverge' means to move apart in different directions, the reverse of two fields 'meeting precisely' at a shared question.", "tag": "reversed"}, {"text": "collapse", "why": "'Collapse' means to fall or fail; the passage describes disciplines meeting, not breaking down.", "tag": "unsupported"}, {"text": "intersect", "why": "Two disciplines that draw on each other and are 'meeting precisely' at a common question cross at a shared point."}, {"text": "compete", "why": "'Compete' implies rivalry; the fields cooperate at a shared question rather than contending against each other.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-intersperse", "wordId": "hd-intersperse", "skill": "words-in-context", "stem": "To keep the dense historical narrative from wearing readers down, the author decided to ______ brief personal anecdotes throughout the chapters, dropping a lighter story here and there among the long stretches of analysis.", "choices": [{"text": "consolidate", "why": "'Consolidate' means to gather into one place, the reverse of scattering short stories 'here and there' across the chapters.", "tag": "reversed"}, {"text": "omit", "why": "'Omit' means to leave out; the author is adding anecdotes, not removing them.", "tag": "unsupported"}, {"text": "summarize", "why": "'Summarize' means to condense; the passage describes distributing whole anecdotes, not compressing them.", "tag": "unsupported"}, {"text": "intersperse", "why": "Placing anecdotes 'throughout the chapters' and 'here and there among' the analysis is scattering them between other material."}], "answer": 3},
{"id": "vq-hd-interweave", "wordId": "hd-interweave", "skill": "words-in-context", "stem": "In her ambitious new novel, the author manages to ______ two seemingly unrelated storylines—one set in a remote fishing village, the other in a bustling capital—until the fates of their characters become utterly inseparable.", "choices": [{"text": "interweave", "why": "The clue 'until the fates of their characters become utterly inseparable' signals blending two threads closely into one, which is exactly what interweave means."}, {"text": "isolate", "why": "To isolate is to set apart or keep separate—the reverse of blending the storylines together.", "tag": "reversed"}, {"text": "truncate", "why": "To truncate is to cut short or shorten; nothing in the passage concerns shortening the narratives.", "tag": "unsupported"}, {"text": "catalog", "why": "To catalog is to list items systematically, which does not capture merging two plots into an inseparable whole.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-inventive", "wordId": "hd-inventive", "skill": "words-in-context", "stem": "Faced with a severe shortage of conventional supplies, the wartime engineers proved remarkably ______, fashioning working radios out of salvaged tin, wax paper, and bits of scavenged wire that no one else had thought to use.", "choices": [{"text": "inventive", "why": "Devising working radios from scavenged scraps that others overlooked demonstrates the creative, resourceful problem-solving that inventive names."}, {"text": "frugal", "why": "Frugal describes thrift with resources, not the imaginative ingenuity of building devices from unlikely scraps.", "tag": "too-specific"}, {"text": "meticulous", "why": "Meticulous means painstakingly careful, which is not the same as generating clever new solutions.", "tag": "unsupported"}, {"text": "conventional", "why": "Conventional means ordinary and unoriginal, the reverse of coming up with novel improvisations.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-invertebrate", "wordId": "hd-invertebrate", "skill": "words-in-context", "stem": "The tide pool teemed with creatures, but the biologist fixed her attention on a single ______—a soft-bodied octopus whose complete absence of any internal skeleton let it squeeze through the narrowest crevice in the rock.", "choices": [{"text": "predator", "why": "Predator names a feeding role shared by countless animals and says nothing about lacking a backbone.", "tag": "too-broad"}, {"text": "invertebrate", "why": "The phrase 'complete absence of any internal skeleton' defines an animal without a backbone—an invertebrate."}, {"text": "vertebrate", "why": "A vertebrate has a backbone, the direct opposite of the skeletonless octopus described.", "tag": "reversed"}, {"text": "crustacean", "why": "Crustaceans are a specific hard-shelled group; an octopus is a mollusk, so the label is out of scope.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-hd-irrelevant-to", "wordId": "hd-irrelevant-to", "skill": "words-in-context", "stem": "The professor dismissed the student's lengthy personal anecdote as ______ the question under discussion; however moving the story might be, it shed no light on the economic principle the class was trying to analyze.", "choices": [{"text": "pertinent to", "why": "Pertinent to means directly relevant, the reverse of a story that sheds no light on the question.", "tag": "reversed"}, {"text": "integral to", "why": "Integral to means an essential part of something, contradicting the anecdote's dismissal as beside the point.", "tag": "reversed"}, {"text": "analogous to", "why": "Analogous to means similar or parallel, but the passage stresses disconnection, not resemblance.", "tag": "unsupported"}, {"text": "irrelevant to", "why": "'Shed no light on' the principle shows the anecdote is not connected to the matter at hand—exactly irrelevant to it."}], "answer": 3},
{"id": "vq-hd-labyrinthine", "wordId": "hd-labyrinthine", "skill": "words-in-context", "stem": "New employees regularly got lost in the agency's ______ approval process—a bewildering maze of forms, overlapping sign-offs, and cross-references that seemed almost deliberately designed to confuse anyone trying to navigate it.", "choices": [{"text": "streamlined", "why": "Streamlined means made simple and efficient, the reverse of a bewildering maze that confuses people.", "tag": "reversed"}, {"text": "transparent", "why": "Transparent means easy to understand, contradicting a process described as confusing to navigate.", "tag": "reversed"}, {"text": "labyrinthine", "why": "'A bewildering maze' of forms and cross-references designed to confuse describes a twisting, intricate tangle—labyrinthine."}, {"text": "lengthy", "why": "Lengthy captures only duration; it misses the maze-like, confusing complexity the passage emphasizes.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-hd-latent", "wordId": "hd-latent", "skill": "words-in-context", "stem": "The virus can remain ______ within the body for years, producing no symptoms whatsoever, until some physical or emotional stressor finally rouses it and triggers a full-blown active infection.", "choices": [{"text": "virulent", "why": "Virulent describes a severe, actively harmful state, the opposite of lying quietly without symptoms.", "tag": "too-specific"}, {"text": "latent", "why": "'Producing no symptoms' for years until something 'rouses it' describes a hidden, dormant presence—latent."}, {"text": "apparent", "why": "Apparent means clearly visible or manifest, contradicting a virus that produces no symptoms.", "tag": "reversed"}, {"text": "contagious", "why": "The virus may indeed be contagious, but the passage stresses its dormancy, not its transmissibility.", "tag": "true-but-irrelevant"}], "answer": 1},
{"id": "vq-hd-localized", "wordId": "hd-localized", "skill": "words-in-context", "stem": "At first the outbreak was ______, affecting only a handful of villages clustered in one narrow river valley; it was not until travelers unknowingly carried the illness overseas that it swelled into a global concern.", "choices": [{"text": "chronic", "why": "Chronic describes something long-lasting in time, but the passage contrasts area, not duration.", "tag": "too-specific"}, {"text": "airborne", "why": "Airborne names a mode of transmission, which the passage never mentions.", "tag": "unsupported"}, {"text": "rampant", "why": "Rampant means spreading unchecked everywhere, the reverse of an outbreak confined to a few villages.", "tag": "reversed"}, {"text": "localized", "why": "'Affecting only a handful of villages in one narrow valley' shows the outbreak was confined to a specific area—localized."}], "answer": 3},
{"id": "vq-hd-morphological", "wordId": "hd-morphological", "skill": "words-in-context", "stem": "When Darwin compared the beaks of finches across the Galapagos, he was making a ______ observation: the birds differed not in behavior or habitat alone but in the very shape and structure of their bodies.", "choices": [{"text": "behavioral", "why": "Behavioral concerns conduct, which the passage explicitly sets aside with 'not in behavior... alone.'", "tag": "reversed"}, {"text": "incidental", "why": "Incidental means minor or occurring by chance, unsupported by a passage stressing physical form.", "tag": "unsupported"}, {"text": "morphological", "why": "'The very shape and structure of their bodies' defines an observation about form and structure, i.e., morphological."}, {"text": "physiological", "why": "Physiological concerns how organisms function, whereas the clue emphasizes shape and structure, not function.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-mystifying", "wordId": "hd-mystifying", "skill": "words-in-context", "stem": "The mass strandings of otherwise healthy pilot whales on Tasmanian beaches remain ______ to marine biologists: despite decades of research into sonar interference, geomagnetic anomalies, and social bonding, no theory adequately explains why the animals repeatedly beach themselves.", "choices": [{"text": "predictable", "why": "Reversed: predictable means able to be foreseen or explained in advance, but the colon elaboration says no theory adequately explains the strandings.", "tag": "reversed"}, {"text": "detrimental", "why": "Detrimental means harmful; strandings do harm whales, but the clue concerns the failure of explanation, not damage, so harm is beside the point.", "tag": "true-but-irrelevant"}, {"text": "mystifying", "why": "The colon introduces the decisive clue—'no theory adequately explains'—so the blank must mean perplexing or impossible to account for."}, {"text": "nebulous", "why": "Nebulous means vague or hazy in form; the strandings themselves are precisely documented events—it is their cause, not their outline, that resists understanding.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-negating", "wordId": "hd-negating", "skill": "words-in-context", "stem": "Economists caution that inflation can quietly undo a raise: a 4 percent salary increase paired with 4 percent annual inflation leaves purchasing power exactly where it began, effectively ______ the gain that workers believe they have secured.", "choices": [{"text": "bolstering", "why": "Reversed: bolstering means strengthening or reinforcing, but the passage describes the raise being canceled out, not enhanced.", "tag": "reversed"}, {"text": "negating", "why": "Purchasing power ends 'exactly where it began,' so the raise is fully canceled out—precisely what negating means."}, {"text": "diminishing", "why": "Intensity mismatch: diminishing means partially reducing, but a gain that leaves purchasing power 'exactly where it began' is wholly erased, not merely lessened.", "tag": "too-broad"}, {"text": "quantifying", "why": "Quantifying means measuring in numerical terms; measuring the gain would not cancel it, and the passage describes erasure, not measurement.", "tag": "true-but-irrelevant"}], "answer": 1},
{"id": "vq-hd-negligible", "wordId": "hd-negligible", "skill": "words-in-context", "stem": "In the yearlong clinical trial, the supplement's effect on cholesterol proved ______: participants' readings fell by less than one percent on average, a change the statisticians deemed indistinguishable from normal day-to-day fluctuation.", "choices": [{"text": "negligible", "why": "A change 'indistinguishable from normal day-to-day fluctuation' is too small to matter at all—exactly what negligible means."}, {"text": "substantial", "why": "Reversed: substantial means considerable in size or importance, but the effect was under one percent and statistically invisible.", "tag": "reversed"}, {"text": "modest", "why": "Precision failure: modest implies a small but genuine effect, yet the passage says the change could not be told apart from random noise—effectively no effect at all.", "tag": "too-broad"}, {"text": "erratic", "why": "Erratic means inconsistent or unpredictable; the passage describes the effect's tiny size, not any irregularity in the results.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-novel", "wordId": "hd-novel", "skill": "words-in-context", "stem": "When Cubist canvases were first exhibited in Paris, critics recognized the style as genuinely ______: rather than refining the perspective techniques inherited from the Renaissance, Picasso and Braque fragmented their subjects in ways no European tradition had anticipated.", "choices": [{"text": "conventional", "why": "Reversed: conventional means following established practice, but the painters broke with inherited techniques in unanticipated ways.", "tag": "reversed"}, {"text": "novel", "why": "The contrast marker 'rather than refining' inherited techniques, plus 'no European tradition had anticipated,' demands a word meaning wholly new—novel."}, {"text": "modern", "why": "Precision failure: modern merely means of recent times—true of all art then being made; the clue requires something unprecedented, not just current.", "tag": "too-broad"}, {"text": "controversial", "why": "Controversial means provoking dispute; the passage never mentions outrage or disagreement, only the unprecedented nature of the approach.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-nuanced", "wordId": "hd-nuanced", "skill": "words-in-context", "stem": "Recent biographies of Thomas Jefferson offer a far more ______ portrait than earlier hagiographies did: instead of casting him simply as hero or hypocrite, they trace how his egalitarian ideals coexisted, often uneasily, with his lifelong practice of enslavement.", "choices": [{"text": "nuanced", "why": "The contrast with casting him 'simply as hero or hypocrite' and the tracing of uneasy coexisting truths signal fine distinctions—a nuanced portrait."}, {"text": "simplistic", "why": "Reversed: simplistic means oversimplified, which describes the crude hero-or-hypocrite framings the new biographies reject.", "tag": "reversed"}, {"text": "critical", "why": "Too narrow: critical implies one-directional condemnation, but the passage rules out portraying Jefferson 'simply as... hypocrite' any more than as hero.", "tag": "too-specific"}, {"text": "definitive", "why": "Definitive means authoritative and final; the contrast in the passage is between subtlety and simplicity, not between complete and incomplete accounts.", "tag": "true-but-irrelevant"}], "answer": 0},
{"id": "vq-hd-operative", "wordId": "hd-operative", "skill": "words-in-context", "stem": "Although the 1966 preservation statute has been amended repeatedly, its central provision remains ______: municipal courts still apply its original review standard whenever a landmark building is threatened with demolition.", "choices": [{"text": "operative", "why": "The colon's elaboration — courts 'still apply' the original standard — shows the provision is in effect and functioning, exactly what operative means."}, {"text": "ornamental", "why": "Reversed: an ornamental provision would exist for show without practical effect, but courts actively enforce this one.", "tag": "reversed"}, {"text": "provisional", "why": "Provisional means temporary or arranged for the time being; a standard applied continuously since 1966 is the opposite of a stopgap, and nothing suggests it awaits replacement.", "tag": "unsupported"}, {"text": "obsolete", "why": "Reversed: obsolete means no longer in use, which directly contradicts the clue that courts still apply the standard.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-ornithologist", "wordId": "hd-ornithologist", "skill": "words-in-context", "stem": "Drawing on six decades of banding records from coastal observatories, the ______ demonstrated that Arctic terns adjust their migratory routes in response to shifting wind patterns, a finding that revised long-held assumptions about avian navigation.", "choices": [{"text": "meteorologist", "why": "Wind patterns figure in the finding, but a meteorologist studies weather itself; the research here — banding birds and tracking tern migration — is the work of a bird specialist.", "tag": "true-but-irrelevant"}, {"text": "ornithologist", "why": "Every clue is bird-specific — banding records, Arctic terns, migratory routes, avian navigation — so the researcher must be an expert who studies birds."}, {"text": "naturalist", "why": "Too broad: a naturalist studies the natural world generally, while the passage's exclusively bird-centered evidence calls for the more precise term for a bird specialist.", "tag": "too-broad"}, {"text": "entomologist", "why": "An entomologist studies insects; nothing in the passage involves insects, only birds.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-overlooked", "wordId": "hd-overlooked", "skill": "words-in-context", "stem": "The astronomical calculations of medieval scholar Levi ben Gerson were largely ______ by later historians of science, appearing in no major survey of the discipline until archival research in the twentieth century restored them to prominence.", "choices": [{"text": "celebrated", "why": "Reversed: celebrated means widely honored, but the calculations appeared in no major survey and needed to be 'restored to prominence.'", "tag": "reversed"}, {"text": "dismissed", "why": "Dismissed implies historians considered the calculations and actively rejected them; the passage indicates the work simply escaped notice, not that it was evaluated and refused.", "tag": "unsupported"}, {"text": "scrutinized", "why": "Scrutinized means examined closely; work absent from every major survey received no attention at all, close or otherwise.", "tag": "unsupported"}, {"text": "overlooked", "why": "Appearing in 'no major survey' until later research 'restored them to prominence' shows the calculations were missed and disregarded — the meaning of overlooked."}], "answer": 3},
{"id": "vq-hd-overshadowed-by", "wordId": "hd-overshadowed-by", "skill": "words-in-context", "stem": "Although Fanny Mendelssohn composed more than four hundred works, her music was long ______ her brother Felix's renown: nineteenth-century concert programs featured his compositions prominently while most of hers remained unpublished during her lifetime.", "choices": [{"text": "overshadowed by", "why": "The colon's contrast — his works featured prominently while hers stayed unpublished — shows her music was eclipsed by his greater fame, the meaning of overshadowed by."}, {"text": "bolstered by", "why": "Reversed: bolstered by means strengthened or helped by, but Felix's renown coincided with her music remaining unpublished, not with its advancement.", "tag": "reversed"}, {"text": "derived from", "why": "Derived from would mean her music originated in his fame; the passage makes no claim that she borrowed from or built on his work.", "tag": "unsupported"}, {"text": "synonymous with", "why": "Synonymous with means so closely associated as to be identified together; her music was scarcely known at all, so it could not have been equated with his renown.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-peripheral", "wordId": "hd-peripheral", "skill": "words-in-context", "stem": "In the historian's account, the coastal trading posts were merely ______ to the empire's economy; the true engines of its wealth were the vast agricultural estates of the interior, which supplied the overwhelming bulk of its revenue.", "choices": [{"text": "peripheral", "why": "The contrast with 'the true engines of its wealth' that supplied 'the overwhelming bulk of revenue' marks the trading posts as marginal and non-central, which peripheral means."}, {"text": "indispensable", "why": "Indispensable means absolutely essential, the reverse of the minor role 'merely' assigns to the trading posts.", "tag": "reversed"}, {"text": "central", "why": "Central means at the core, directly contradicting the passage's claim that the estates, not the posts, were the true source of wealth.", "tag": "reversed"}, {"text": "lucrative", "why": "Lucrative means highly profitable, but the passage says the posts contributed little; it never calls them profitable.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-persist", "wordId": "hd-persist", "skill": "words-in-context", "stem": "Even after the invasive beetles were completely eradicated from the forest, the ecological damage they had caused proved able to ______: weakened trees kept dying for years, and the altered soil chemistry showed no sign of returning to its former state.", "choices": [{"text": "subside", "why": "Subside means to lessen and die down, the reverse of damage that keeps going 'for years' with 'no sign of returning' to normal.", "tag": "reversed"}, {"text": "persist", "why": "'Kept dying for years' and 'no sign of returning to its former state' show the damage continues and endures, which is what persist means."}, {"text": "reverse", "why": "Reverse means to undo or turn back, contradicting damage that shows no sign of recovering.", "tag": "reversed"}, {"text": "intensify", "why": "Intensify means to grow stronger, but the passage describes damage that lingers unchanged, not damage that worsens.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-powerful", "wordId": "hd-powerful", "skill": "words-in-context", "stem": "The abolitionist's memoir proved unexpectedly ______: its vivid firsthand testimony swayed thousands of previously undecided readers and was cited for decades afterward as a decisive influence on public opinion.", "choices": [{"text": "powerful", "why": "Swaying thousands of readers and serving as 'a decisive influence on public opinion' shows the memoir had great force and impact, which is what powerful means."}, {"text": "obscure", "why": "Obscure means little known or unnoticed, the reverse of a work cited for decades and credited with shaping opinion.", "tag": "reversed"}, {"text": "derivative", "why": "Derivative means unoriginal, imitative of others' work; the passage praises the memoir's impact, not its originality.", "tag": "unsupported"}, {"text": "tedious", "why": "Tedious means dull and tiresome, contradicting a book that gripped and moved thousands of readers.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-precariousness", "wordId": "hd-precariousness", "skill": "words-in-context", "stem": "The report drew attention to the ______ of the day laborers' situation: hired only from one morning to the next, without contracts or savings, they could be plunged into destitution by a single missed shift.", "choices": [{"text": "security", "why": "Security means safety and stability, the reverse of a situation in which one missed shift means ruin.", "tag": "reversed"}, {"text": "precariousness", "why": "Being hired day to day with no contracts or savings and vulnerable to instant destitution describes an unstable, chancy state, which is what precariousness means."}, {"text": "monotony", "why": "Monotony means tiresome sameness; the passage stresses instability and risk, not dull repetition.", "tag": "true-but-irrelevant"}, {"text": "affluence", "why": "Affluence means wealth, the opposite of workers with no savings who could fall into destitution.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-precursors-of", "wordId": "hd-precursors-of", "skill": "words-in-context", "stem": "Physicians now recognize that certain mild neurological symptoms are ______ more serious degenerative disease: appearing years in advance, these subtle signs warn clinicians of conditions that will only fully emerge much later.", "choices": [{"text": "byproducts of", "why": "A byproduct is an incidental result of something already present, but the passage stresses that the signs come first and foreshadow what is to come.", "tag": "unsupported"}, {"text": "precursors of", "why": "The clue 'appearing years in advance' and 'warn of conditions that will emerge later' names early indications that foreshadow a future development."}, {"text": "remnants of", "why": "Remnants are leftovers pointing backward to something past, but these signs point forward to disease not yet arrived.", "tag": "reversed"}, {"text": "safeguards against", "why": "A safeguard protects against harm, the opposite function of a warning sign that heralds oncoming disease.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-predatory", "wordId": "hd-predatory", "skill": "words-in-context", "stem": "Marine biologists studying the reef noted that the eel's behavior was distinctly ______: it lay concealed within crevices, then lunged to seize the smaller fish that strayed within reach, consuming several of them each hour.", "choices": [{"text": "territorial", "why": "Territoriality is about defending an area, which does not explain the eel's hunting and consuming of prey.", "tag": "too-specific"}, {"text": "gregarious", "why": "Means sociable and fond of company; nothing about the solitary ambush hunting supports it.", "tag": "unsupported"}, {"text": "predatory", "why": "The clue 'lunged to seize the smaller fish... consuming several' describes preying on other organisms for food—the core of predatory."}, {"text": "dormant", "why": "Means inactive or sleeping, the reverse of the active, aggressive hunting the passage depicts.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-predetermined", "wordId": "hd-predetermined", "skill": "words-in-context", "stem": "In the traditional ceremony nothing is left to improvisation: the sequence of dances, the order of the speakers, and the exact moment of the feast are all ______, fixed by custom long before any of the participants arrive.", "choices": [{"text": "arbitrary", "why": "Means based on whim or chance, but the passage says the order is fixed by longstanding custom, which gives it a definite basis.", "tag": "unsupported"}, {"text": "spontaneous", "why": "Means improvised on the spot, directly contradicting 'nothing is left to improvisation.'", "tag": "reversed"}, {"text": "controversial", "why": "Means disputed or contested; the passage mentions no disagreement about the order at all.", "tag": "unsupported"}, {"text": "predetermined", "why": "The clue 'fixed by custom long before any of the participants arrive' means settled in advance—exactly predetermined."}], "answer": 3},
{"id": "vq-hd-predictive-of", "wordId": "hd-predictive-of", "skill": "words-in-context", "stem": "Analyzing decades of records, the researchers found that a patient's resting heart rate was strongly ______ later cardiovascular problems: elevated readings reliably anticipated illnesses that developed only years afterward.", "choices": [{"text": "unrelated to", "why": "Means having no connection, the reverse of the strong forecasting link the data show.", "tag": "reversed"}, {"text": "predictive of", "why": "The clue 'reliably anticipated illnesses that developed only years afterward' describes a present measure indicating a future outcome—predictive of."}, {"text": "symptomatic of", "why": "A symptom is a present sign of an already-existing condition, but the passage emphasizes readings that precede illness by years.", "tag": "unsupported"}, {"text": "derivative of", "why": "Means copied from or originating in something, which misstates the forecasting relationship the passage describes.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-prefiguring", "wordId": "hd-prefiguring", "skill": "words-in-context", "stem": "Critics regard the painter's early monochrome sketches as ______ the radical abstraction of his later career: though modest in scale, they already hint at techniques he would only fully develop decades afterward.", "choices": [{"text": "obscuring", "why": "Means hiding or darkening, but the passage says the sketches reveal—not conceal—what is to come.", "tag": "reversed"}, {"text": "documenting", "why": "Means merely recording an existing fact, missing the sense of foreshadowing a future development.", "tag": "unsupported"}, {"text": "prefiguring", "why": "The clue 'hint at techniques he would only fully develop decades afterward' means foreshadowing what will come—prefiguring."}, {"text": "recalling", "why": "Means bringing to mind something past, pointing backward, whereas the sketches point forward to his later work.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-prescribed", "wordId": "hd-prescribed", "skill": "words-in-context", "stem": "Patients recovering from the surgery must follow the exact regimen ______ by their physician—the specified doses, the timing, and the duration—and are cautioned never to alter the plan on their own.", "choices": [{"text": "forbidden", "why": "Means prohibited, the reverse of a regimen the patient is ordered to follow.", "tag": "reversed"}, {"text": "prescribed", "why": "The clue 'exact regimen... specified doses, timing, and duration' and 'never to alter the plan' names a required course ordered by the physician—prescribed."}, {"text": "suggested", "why": "Implies an optional recommendation, but the passage stresses an exact, mandatory regimen the patient must not change.", "tag": "too-broad"}, {"text": "documented", "why": "Means merely recorded in writing, which says nothing about ordering a required course of treatment.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-proclaims", "wordId": "hd-proclaims", "skill": "words-in-context", "stem": "In the play's climactic scene, the hero steps to the center of the stage and boldly ______ his loyalty to the exiled queen, shouting his allegiance so loudly that every other character present can hear it.", "choices": [{"text": "conceals", "why": "Means to hide, the reverse of the loud, open declaration the scene depicts.", "tag": "reversed"}, {"text": "records", "why": "Means to write down for later, but the scene shows a spoken, public shout, not a written note.", "tag": "unsupported"}, {"text": "proclaims", "why": "The clue 'shouting his allegiance so loudly that every other character... can hear it' means publicly declaring—proclaims."}, {"text": "renounces", "why": "Means to formally reject or give up, but the hero is affirming his loyalty, not disavowing it.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-proficient", "wordId": "hd-proficient", "skill": "words-in-context", "stem": "After years of daily practice, the violinist had become so ______ that she could sight-read the most demanding scores flawlessly and perform intricate passages that other seasoned musicians still struggled to master.", "choices": [{"text": "inept", "why": "Means clumsy and unskilled, the reverse of the flawless mastery the passage describes.", "tag": "reversed"}, {"text": "apathetic", "why": "Means indifferent or uninterested, but the passage speaks to her ability, not her attitude.", "tag": "unsupported"}, {"text": "renowned", "why": "Means widely famous, but the clue concerns her skill—flawless sight-reading—rather than her public reputation.", "tag": "unsupported"}, {"text": "proficient", "why": "The clue 'could sight-read the most demanding scores flawlessly' and outperform seasoned musicians means highly skilled and competent—proficient."}], "answer": 3},
{"id": "vq-hd-profusion-of", "wordId": "hd-profusion-of", "skill": "words-in-context", "domain": "science", "difficulty": "hard", "targetSeconds": 50, "stem": "When the desert finally received rain after years of drought, the normally barren valley erupted with a ______ wildflowers, blanketing the sand so densely that the ground itself became invisible beneath the blooms.", "choices": [{"text": "dearth of", "why": "Reversed: a dearth is a scarcity or lack, contradicting a valley blanketed so densely the ground disappears.", "tag": "reversed"}, {"text": "profusion of", "why": "The clues 'blanketing the sand so densely' and 'the ground itself became invisible' point to an overwhelming abundance."}, {"text": "smattering of", "why": "Too small: a smattering is a slight, scattered amount, contradicting the dense, ground-covering bloom.", "tag": "too-specific"}, {"text": "succession of", "why": "Wrong dimension: a succession describes things following one another in time, not a measure of sheer quantity.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-quarrel-about", "wordId": "hd-quarrel-about", "skill": "words-in-context", "domain": "history", "difficulty": "hard", "targetSeconds": 50, "stem": "For decades, the followers of Newton and Leibniz continued to bitterly ______ who had invented calculus first, each camp accusing the other of plagiarism and refusing to concede even the smallest point.", "choices": [{"text": "agree about", "why": "Reversed: to agree is to reach consensus, contradicting camps 'accusing the other of plagiarism' and refusing to concede.", "tag": "reversed"}, {"text": "quarrel about", "why": "The clues 'bitterly,' 'accusing the other of plagiarism,' and 'refusing to concede' point to a heated, ongoing dispute."}, {"text": "reminisce about", "why": "Wrong tone: to reminisce is to recall fondly, which clashes with the bitter, accusatory dispute described.", "tag": "unsupported"}, {"text": "speculate about", "why": "Unsupported: to speculate is to guess or theorize, but the passage depicts an angry disagreement, not idle conjecture.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-questioned", "wordId": "hd-questioned", "skill": "words-in-context", "domain": "history", "difficulty": "hard", "targetSeconds": 50, "stem": "When Galileo's telescopic observations contradicted long-held beliefs, many scholars openly ______ the reliability of his instrument, insisting that the strange moons he claimed to see were mere illusions produced by flawed lenses.", "choices": [{"text": "endorsed", "why": "Reversed: to endorse is to affirm or back, the opposite of scholars insisting the instrument produced illusions.", "tag": "reversed"}, {"text": "verified", "why": "Reversed: to verify is to confirm as accurate, contradicting their claim that the sightings were mere illusions.", "tag": "reversed"}, {"text": "documented", "why": "Wrong sense: to document is to record neutrally, but the scholars actively voiced doubt rather than merely noting the instrument.", "tag": "unsupported"}, {"text": "questioned", "why": "'Insisting the moons were illusions produced by flawed lenses' shows the scholars expressed doubt about and challenged the instrument's reliability."}], "answer": 3},
{"id": "vq-hd-recants", "wordId": "hd-recants", "skill": "words-in-context", "stem": "Under mounting pressure from the tribunal, the astronomer publicly ______ the very theory he had championed for decades, declaring before the assembly that he now rejected the claims his earlier writings had so boldly defended.", "choices": [{"text": "reaffirms", "why": "Reversed: it means to restate and reassert a belief, the opposite of the astronomer now rejecting his own claims.", "tag": "reversed"}, {"text": "circulates", "why": "Unsupported: it means to spread or distribute, a sense nothing in the passage supports.", "tag": "unsupported"}, {"text": "recants", "why": "'Declaring... that he now rejected the claims his earlier writings had... defended' is precisely a formal withdrawal of a previously held belief."}, {"text": "revises", "why": "A near-synonym that fails on precision: it means to amend or partly alter, but the passage shows the theory wholly renounced, not merely adjusted.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-hd-refinements-of", "wordId": "hd-refinements-of", "skill": "words-in-context", "stem": "The engineers did not abandon the original prototype; instead, each new model represented a series of ______ it, with small adjustments that made the mechanism smoother, quieter, and more precise than before.", "choices": [{"text": "departures from", "why": "Means moves away or deviations; the passage states the engineers did not abandon the prototype, so this reverses the direction.", "tag": "reversed"}, {"text": "replacements for", "why": "Means substitutions of something new; they kept the same design and improved it rather than swapping it out.", "tag": "unsupported"}, {"text": "refinements of", "why": "The 'small adjustments that made the mechanism smoother... and more precise' are exactly polishing improvements to the existing design."}, {"text": "criticisms of", "why": "Means expressions of disapproval; the passage describes physical improvements, not judgments about the design.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-regretted", "wordId": "hd-regretted", "skill": "words-in-context", "stem": "In his later memoirs, the general ______ his hasty decision to attack at dawn; had he waited for reinforcements, he wrote, thousands of lives might have been spared, and the memory of that morning haunted him for the rest of his days.", "choices": [{"text": "celebrated", "why": "Means to honor with joy or pride; the general felt sorrow, as the haunting memory shows, so this reverses the emotion.", "tag": "reversed"}, {"text": "regretted", "why": "'Thousands might have been spared' and the memory that 'haunted him' signal deep remorse over the decision."}, {"text": "downplayed", "why": "Means to minimize the importance of; the general dwelt on the decision heavily rather than making light of it.", "tag": "unsupported"}, {"text": "recounted", "why": "Means merely to narrate; this neutral word ignores the sorrow and remorse the passage emphasizes.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-hd-remember", "wordId": "hd-remember", "skill": "words-in-context", "stem": "The elderly violinist could no longer read a menu without her glasses, yet she could still ______ every note of the concerto she had first performed sixty years earlier, the melody returning to her mind as vividly as on that distant evening.", "choices": [{"text": "memorize", "why": "Means to learn by heart for the first time; she is recalling a piece she has long known, not newly committing it to memory.", "tag": "reversed"}, {"text": "remember", "why": "'The melody returning to her mind... as on that distant evening' describes recalling something from the past."}, {"text": "improvise", "why": "Means to invent spontaneously; the notes are fixed and recalled, not made up.", "tag": "unsupported"}, {"text": "transcribe", "why": "Means to write out in notation; she brings the notes to mind, not to paper.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-hd-replicable", "wordId": "hd-replicable", "skill": "words-in-context", "stem": "A key standard for trustworthy research is that its results be ______: any independent team that follows the published protocol should be able to reproduce the same outcome, whereas a finding only its original author can ever obtain cannot be confirmed by anyone else.", "choices": [{"text": "confidential", "why": "Means kept secret; trustworthy results must be openly reproducible, not hidden, so this reverses the meaning.", "tag": "reversed"}, {"text": "replicable", "why": "'Any independent team... should be able to reproduce the same outcome' defines results capable of being repeated."}, {"text": "generalizable", "why": "Means applicable to broader populations or cases; the passage concerns repeating the same procedure, not extending it to new groups.", "tag": "unsupported"}, {"text": "provisional", "why": "Means tentative or temporary; nothing suggests the results are only preliminary.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-representative-of", "wordId": "hd-representative-of", "skill": "words-in-context", "stem": "To ensure the poll's accuracy, the researchers selected participants whose ages, incomes, and backgrounds mirrored those of the country as a whole, so that the small sample would be truly ______ the entire population it was meant to describe.", "choices": [{"text": "superior to", "why": "Means better in quality than; typicality concerns resemblance, not ranking one group above another.", "tag": "unsupported"}, {"text": "skewed toward", "why": "Means distorted in favor of one subgroup; a sample that mirrors the whole population avoids exactly such distortion.", "tag": "reversed"}, {"text": "representative of", "why": "The sample 'mirrored those of the country as a whole,' so it is typical of and characteristic of the larger group."}, {"text": "independent of", "why": "Means unconnected to or uninfluenced by; the sample was built to resemble the population, not to stand apart from it.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-repudiates", "wordId": "hd-repudiates", "skill": "words-in-context", "difficulty": "hard", "stem": "The essay forcefully ______ the romantic notion that great art springs from suffering alone, dismissing the idea as a sentimental myth that conveniently ignores the years of disciplined labor behind every masterpiece.", "choices": [{"text": "embraces", "why": "Reversed: to embrace an idea is to accept it eagerly, yet the essay dismisses the notion as a myth.", "tag": "reversed"}, {"text": "exaggerates", "why": "To exaggerate is to overstate; the essay is attacking the idea, not inflating it.", "tag": "unsupported"}, {"text": "repudiates", "why": "Correct: 'dismissing the idea as a sentimental myth' shows the essay rejects and disowns the notion."}, {"text": "questions", "why": "To question is merely to raise doubt, but 'dismissing... as a myth' shows a flat rejection far stronger than mild doubt.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-hd-require", "wordId": "hd-require", "skill": "words-in-context", "difficulty": "hard", "stem": "Deep-sea anglerfish ______ specialized light-producing organs to survive in waters where sunlight never reaches; without such adaptations, the fish could neither lure prey toward their jaws nor locate mates in the darkness.", "choices": [{"text": "discourage", "why": "Reversed: to discourage is to deter or hinder, but the organs are indispensable to the fish, not something they hold back.", "tag": "reversed"}, {"text": "mimic", "why": "To mimic is to imitate; the fish possess and depend on the organs rather than copying them.", "tag": "unsupported"}, {"text": "tolerate", "why": "To tolerate is merely to put up with, but 'without such adaptations... could neither... nor' shows the organs are essential, not just endured.", "tag": "too-broad"}, {"text": "require", "why": "Correct: 'without such adaptations, the fish could neither... nor' establishes that the organs are necessary, which is what to require means."}], "answer": 3},
{"id": "vq-hd-restrained", "wordId": "hd-restrained", "skill": "words-in-context", "difficulty": "hard", "stem": "Critics praised the architect's ______ use of ornament: rather than crowding every surface with carvings, she allowed only a few carefully chosen details to stand out against broad expanses of plain, uncluttered stone.", "choices": [{"text": "extravagant", "why": "Reversed: extravagant means excessive or lavish, the opposite of 'a few carefully chosen details' on plain walls.", "tag": "reversed"}, {"text": "haphazard", "why": "Haphazard means random or unplanned, but her details were 'carefully chosen,' the opposite of careless.", "tag": "unsupported"}, {"text": "meager", "why": "Meager implies deficient or insufficient, yet the passage praises her ornament as deliberate and effective, not lacking.", "tag": "too-specific"}, {"text": "restrained", "why": "Correct: 'rather than crowding every surface... only a few... plain, uncluttered' describes controlled, non-excessive use of ornament."}], "answer": 3},
{"id": "vq-hd-restricted", "wordId": "hd-restricted", "skill": "words-in-context", "difficulty": "hard", "stem": "The rare salamander's range is severely ______: the animal survives only in a handful of cold mountain streams and cannot tolerate the warmer lowland waters that surround its narrow highland refuge on every side.", "choices": [{"text": "restricted", "why": "Correct: 'only in a handful of... streams' and 'cannot tolerate the... waters that surround it' show a range confined within narrow boundaries."}, {"text": "widespread", "why": "Reversed: widespread means spread over a large area, but the salamander lives in only a few streams.", "tag": "reversed"}, {"text": "degraded", "why": "Degraded concerns damage to quality; the clue is about how small and confined the range is, not its condition.", "tag": "true-but-irrelevant"}, {"text": "temporary", "why": "Temporary concerns duration, but the passage describes the spatial limits of the range, not how long it lasts.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-routine", "wordId": "hd-routine", "skill": "words-in-context", "difficulty": "hard", "stem": "For the veteran pilots, a maneuver that terrified novices had become entirely ______: they had executed it so many thousands of times over their careers that it now demanded no conscious thought at all.", "choices": [{"text": "hazardous", "why": "The maneuver may be dangerous, but the clue is about how habitual it became, not its level of risk.", "tag": "true-but-irrelevant"}, {"text": "bewildering", "why": "Reversed: bewildering means confusing, yet the pilots perform the maneuver so automatically it requires no thought.", "tag": "reversed"}, {"text": "routine", "why": "Correct: 'executed it so many thousands of times' until it 'demanded no conscious thought' describes a habitual, fixed-pattern action."}, {"text": "optional", "why": "Optional means a matter of choice; nothing suggests the pilots could decline to perform the maneuver.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-satisfactory", "wordId": "hd-satisfactory", "skill": "words-in-context", "stem": "The inspector's report rated the bridge's condition as merely ______: the structure met every minimum safety requirement, yet it displayed none of the reinforcements that would have earned a higher classification.", "choices": [{"text": "exemplary", "why": "Exemplary means outstanding, a model of excellence; 'merely' and the absence of anything beyond minimum requirements rule out high praise.", "tag": "reversed"}, {"text": "deficient", "why": "Deficient means failing to meet requirements, but the colon states the bridge 'met every minimum safety requirement.'", "tag": "reversed"}, {"text": "satisfying", "why": "Satisfying means emotionally gratifying or pleasing; a technical inspection rating concerns meeting standards, and nothing in the passage involves pleasure or contentment.", "tag": "unsupported"}, {"text": "satisfactory", "why": "The colon defines the blank: meeting every minimum requirement while exceeding none is precisely satisfactory — adequate and acceptable, no more."}], "answer": 3},
{"id": "vq-hd-satisfying", "wordId": "hd-satisfying", "skill": "words-in-context", "stem": "Readers who found the mystery's final chapter deeply ______ pointed to the way every stray clue was woven into the resolution, producing the pleasurable sense of completeness that devotees of the genre crave.", "choices": [{"text": "perplexing", "why": "Perplexing means confusing, but the chapter resolves 'every stray clue' — the opposite of leaving readers puzzled.", "tag": "reversed"}, {"text": "satisfying", "why": "The 'pleasurable sense of completeness that... devotees crave' glosses the blank: the ending is gratifying and gives contentment — satisfying."}, {"text": "satisfactory", "why": "Satisfactory means merely adequate, meeting minimum expectations; it is too weak for 'deeply' and for the pleasure and craving the passage describes.", "tag": "too-specific"}, {"text": "predictable", "why": "Predictable means easily foreseen; the passage praises how the clues were resolved and says nothing about readers anticipating the ending.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-settled", "wordId": "hd-settled", "skill": "words-in-context", "stem": "Whether birds descended from theropod dinosaurs was once fiercely debated among paleontologists, but the question is now ______: the discovery of numerous feathered fossils in Liaoning Province ended serious disagreement within the field.", "choices": [{"text": "contentious", "why": "Contentious means provoking dispute; the colon says the fossil discoveries 'ended serious disagreement' — the opposite of ongoing controversy.", "tag": "reversed"}, {"text": "unanimous", "why": "Unanimous describes people or votes in full agreement; a question itself cannot be unanimous, and the blank must characterize the question as resolved.", "tag": "unsupported"}, {"text": "settled", "why": "The contrast with 'once fiercely debated' plus the colon ('ended serious disagreement') shows the question is resolved, no longer subject to dispute — settled."}, {"text": "trivial", "why": "Trivial means unimportant; that the debate ended says nothing about the question losing importance.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-simultaneous", "wordId": "hd-simultaneous", "skill": "words-in-context", "stem": "Calculus offers a famous case of ______ discovery: working independently during the 1670s, Newton in England and Leibniz on the Continent each arrived at the method at nearly the same time, unaware of the other's progress.", "choices": [{"text": "simultaneous", "why": "The colon supplies the clue — the two mathematicians arrived at the method 'at nearly the same time' — so the discovery was simultaneous, occurring at the same time."}, {"text": "collaborative", "why": "Collaborative means done by working together, but the passage stresses they worked 'independently' and 'unaware of the other's progress.'", "tag": "reversed"}, {"text": "accidental", "why": "Accidental means happening by chance; both men deliberately developed the method, and nothing suggests luck.", "tag": "unsupported"}, {"text": "derivative", "why": "Derivative means copied or adapted from another's work; each worked unaware of the other, so neither result was borrowed.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-straightforward", "wordId": "hd-straightforward", "skill": "words-in-context", "difficulty": "hard", "domain": "technology", "targetSeconds": 45, "stem": "Reviewers praised the software's setup as remarkably ______: each step was clearly labeled, required no technical background whatsoever, and could be completed by a first-time user in only a few minutes.", "choices": [{"text": "straightforward", "why": "\"clearly labeled,\" needing \"no technical background,\" and finishable in minutes marks the process as clear and uncomplicated."}, {"text": "convoluted", "why": "Convoluted means intricate and hard to follow, the opposite of clearly labeled steps anyone can complete.", "tag": "reversed"}, {"text": "tedious", "why": "Tedious means tiresomely long, addressing boredom rather than the ease of understanding the clues describe.", "tag": "unsupported"}, {"text": "arduous", "why": "Arduous means demanding great effort, contradicting a setup a first-time user finishes in minutes.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-subduction", "wordId": "hd-subduction", "skill": "words-in-context", "difficulty": "hard", "domain": "geology", "targetSeconds": 45, "stem": "Geologists explained that the coastal chain of volcanoes had formed through ______: one oceanic plate was steadily sliding beneath the neighboring continental plate and melting as it plunged into the hot mantle below.", "choices": [{"text": "erosion", "why": "Erosion is the wearing away of surface material by wind or water, not the sinking of one plate beneath another.", "tag": "unsupported"}, {"text": "sedimentation", "why": "Sedimentation is the settling and deposit of particles, a surface process unrelated to a plate diving into the mantle.", "tag": "unsupported"}, {"text": "condensation", "why": "Condensation is a gas cooling into liquid, a wrong-domain process with nothing to do with tectonic plates.", "tag": "unsupported"}, {"text": "subduction", "why": "One plate \"sliding beneath\" another and melting in the mantle is the exact process the term names."}], "answer": 3},
{"id": "vq-hd-substantial", "wordId": "hd-substantial", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "When the archaeologist tallied the artifacts recovered from the single burial chamber, the haul proved ______: more than four hundred gold ornaments, dozens of ceremonial vessels, and a cache of weapons far exceeding anything found at comparable sites.", "choices": [{"text": "substantial", "why": "The enumerated counts and the phrase 'far exceeding anything found at comparable sites' signal a find that is considerable in amount and size."}, {"text": "adequate", "why": "Means merely enough to meet a need — a narrower, weaker claim than 'considerable'; the haul 'far exceeded' what other sites held, so this understates it.", "tag": "too-specific"}, {"text": "negligible", "why": "Means so small as to be not worth counting — the opposite of a haul that far exceeds every comparable find.", "tag": "reversed"}, {"text": "provisional", "why": "Means temporary or tentative; nothing in the passage concerns how long the find will stand, only how large it is.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-substantiating", "wordId": "hd-substantiating", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "Historians had long dismissed the merchant's diary as fanciful, but a cache of ______ documents — customs ledgers, shipping manifests, and signed contracts — confirmed that nearly every voyage it described had in fact taken place.", "choices": [{"text": "conflicting", "why": "Means clashing or contradictory; the documents agree with the diary and prove it true rather than dispute it.", "tag": "reversed"}, {"text": "clarifying", "why": "Means making something easier to understand; the documents do more than explain — they establish that the described events truly occurred.", "tag": "too-specific"}, {"text": "substantiating", "why": "The ledgers and contracts 'confirmed that nearly every voyage ... had in fact taken place,' so the documents supply evidence for the diary's truth."}, {"text": "circulating", "why": "Means being passed around or distributed; the passage concerns whether the documents prove the diary true, not how widely they spread.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-subsumed-in", "wordId": "hd-subsumed-in", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "In the revised classification, the dozens of regional dialects that scholars once treated as independent tongues were ______ a single language family, their distinctive features recast as mere local variations of one broader system.", "choices": [{"text": "isolated from", "why": "Means set apart or separated; the dialects are being folded together, not held apart.", "tag": "reversed"}, {"text": "derived from", "why": "Points to origin or descent, but the passage describes present membership in one category, not where the dialects came from.", "tag": "unsupported"}, {"text": "appended to", "why": "Means tacked on externally; the dialects are absorbed within the family as variations of it, not attached to its outside.", "tag": "too-specific"}, {"text": "subsumed in", "why": "The dialects are 'recast as mere local variations of one broader system,' i.e., absorbed within a larger, more comprehensive category."}], "answer": 3},
{"id": "vq-hd-succumb", "wordId": "hd-succumb", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "For weeks the stranded climbers rationed their food and fought off despair, but as the storms refused to break and their strength ebbed, even the most resolute among them finally began to ______, worn down at last by exhaustion and biting cold.", "choices": [{"text": "resist", "why": "Means to fight off; the phrase 'worn down at last' shows the climbers ceasing to fight, not continuing to.", "tag": "reversed"}, {"text": "succumb", "why": "'Even the most resolute ... worn down at last by exhaustion and biting cold' shows them yielding to a harmful, overpowering force."}, {"text": "relent", "why": "Means to soften one's stance or become less severe toward others; the climbers are physically overcome by conditions, not easing a position.", "tag": "too-specific"}, {"text": "recover", "why": "Means to regain strength; it contradicts 'worn down at last' by exhaustion.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-supplemental-to", "wordId": "hd-supplemental-to", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "The editors are careful to explain that the online appendix is not the heart of the study; the printed article stands on its own, and the data tables posted on the website are merely ______ it, offered only for readers who wish to check the calculations themselves.", "choices": [{"text": "central to", "why": "Means essential and at the core; the passage states outright that the tables are 'not the heart of the study.'", "tag": "reversed"}, {"text": "identical to", "why": "Means the same as; the tables provide extra material for verification, they are not a duplicate of the article.", "tag": "unsupported"}, {"text": "preliminary to", "why": "Means coming before as a precursor; the tables are an optional add-on for interested readers, not a lead-in to the article.", "tag": "too-specific"}, {"text": "supplemental to", "why": "Since the article 'stands on its own' and the tables are 'merely' extra material offered for checking, they provide additional support to it."}], "answer": 3},
{"id": "vq-hd-surmised", "wordId": "hd-surmised", "skill": "words-in-context", "stem": "Because the excavation had yielded only a handful of charred seeds and a single broken storage jar, the archaeologist could not prove what the settlement's inhabitants had eaten; from these scant traces she nonetheless ______ that the community had depended chiefly on cultivated grain.", "choices": [{"text": "surmised", "why": "The clues 'scant traces' and 'could not prove' signal a conclusion drawn from limited evidence, which is exactly what 'surmised' (inferred from little information) means."}, {"text": "demonstrated", "why": "'Demonstrated' means proved conclusively, but the passage stresses she 'could not prove' her idea, so it overstates her certainty.", "tag": "reversed"}, {"text": "dismissed", "why": "'Dismissed' means rejected or set aside, yet she in fact accepted the grain hypothesis, so this reverses her stance.", "tag": "reversed"}, {"text": "fabricated", "why": "'Fabricated' means invented dishonestly, but nothing implies deception—she reasoned from genuine physical traces.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-tolerate", "wordId": "hd-tolerate", "skill": "words-in-context", "stem": "The new manager was famous for her rigid standards: minor lateness that previous supervisors had been willing to ______ she treated as a serious offense, issuing formal warnings for infractions others would scarcely have bothered to mention.", "choices": [{"text": "penalize", "why": "'Penalize' means to punish, but the contrast requires the opposite—what the old supervisors let pass.", "tag": "reversed"}, {"text": "endorse", "why": "'Endorse' means to actively approve, whereas 'tolerate' means merely to permit something without objection, not to praise it.", "tag": "too-broad"}, {"text": "tolerate", "why": "The contrast with the strict manager who treated lateness as an offense shows the old supervisors would 'tolerate' it—accept it without objection."}, {"text": "prohibit", "why": "'Prohibit' means to forbid, the reverse of quietly putting up with minor lateness.", "tag": "reversed"}], "answer": 2},
{"id": "vq-hd-unbiased", "wordId": "hd-unbiased", "skill": "words-in-context", "stem": "To ensure the survey's findings were ______, the pollsters randomized the sequence of questions and hired interviewers who had no personal stake in the outcome, deliberately guarding against any subtle tilt toward one preferred result.", "choices": [{"text": "conclusive", "why": "Means decisive or final; the measures described protect fairness of process, not the certainty of the conclusion.", "tag": "true-but-irrelevant"}, {"text": "partisan", "why": "Means favoring one side; this is the very tilt the pollsters were working to prevent, so it reverses the intended meaning.", "tag": "reversed"}, {"text": "exhaustive", "why": "Means thorough or complete in coverage; the safeguards concern neutrality, not how much ground the survey covers.", "tag": "unsupported"}, {"text": "unbiased", "why": "Interviewers with 'no personal stake' and guarding 'against any tilt toward one preferred result' point directly to impartiality."}], "answer": 3},
{"id": "vq-hd-undulate", "wordId": "hd-undulate", "skill": "words-in-context", "stem": "As the steady breeze swept across the ripe field, the tall stalks of wheat began to ______, rising and dipping in long rolling waves that traveled smoothly from one distant fence line all the way to the other.", "choices": [{"text": "wither", "why": "Means to dry up and shrivel; the passage describes graceful motion in the wind, not decay.", "tag": "unsupported"}, {"text": "undulate", "why": "'Rising and dipping in long rolling waves' precisely names the smooth up-and-down motion the word denotes."}, {"text": "scatter", "why": "Means to disperse in different directions; the stalks stay rooted and move in a coordinated wave, not apart.", "tag": "unsupported"}, {"text": "stiffen", "why": "Means to become rigid; this contradicts the fluid, rolling movement the passage describes.", "tag": "reversed"}], "answer": 1},
{"id": "vq-hd-unimportant", "wordId": "hd-unimportant", "skill": "words-in-context", "stem": "The archivist cautioned visitors never to dismiss the ledger's cramped marginal notes as ______: what looked at first like idle scribbles about the weather and the day's meals later proved essential to fixing the date of the entire manuscript.", "choices": [{"text": "indecipherable", "why": "Means impossible to read; the contrast is about the notes' significance being underrated, not about their legibility.", "tag": "unsupported"}, {"text": "authentic", "why": "Means genuine; the passage concerns whether the notes mattered, not whether they were real.", "tag": "unsupported"}, {"text": "unimportant", "why": "The warning against dismissing notes that 'later proved essential' signals the mistaken view was that they were insignificant."}, {"text": "fraudulent", "why": "Means deliberately faked; nothing suggests the notes were forged, only that their value was almost overlooked.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-hd-unknown", "wordId": "hd-unknown", "skill": "words-in-context", "stem": "When the strange fossil was first unearthed in a quarry in 1901, the species it belonged to was entirely ______: no catalogue described such an animal, no naturalist of the day could put a name to it, and decades passed before it was formally classified.", "choices": [{"text": "extinct", "why": "Means no longer living; while a fossil species may be, the passage is about the creature not yet being identified, not about its survival.", "tag": "true-but-irrelevant"}, {"text": "commonplace", "why": "Means ordinary and familiar; this reverses the sense, since no catalogue or naturalist recognized the animal at all.", "tag": "reversed"}, {"text": "fragmentary", "why": "Means incomplete in pieces; this would describe the fossil's condition, not the state of scientific knowledge about the species.", "tag": "unsupported"}, {"text": "unknown", "why": "That 'no catalogue described' it and 'no naturalist could put a name to it' until decades later defines a species not yet identified or recognized."}], "answer": 3},
{"id": "vq-hd-unobtrusive", "wordId": "hd-unobtrusive", "skill": "words-in-context", "stem": "The museum's new climate sensors were engineered to be ______: tucked discreetly behind the cornices and painted to match the surrounding plaster, they tracked humidity and temperature around the clock without ever drawing a single visitor's eye.", "choices": [{"text": "unobtrusive", "why": "Hidden behind cornices, color-matched to the plaster, and never drawing a visitor's eye describes devices that avoid attracting attention."}, {"text": "conspicuous", "why": "Means highly visible and attention-grabbing; this is the opposite of sensors deliberately hidden from view.", "tag": "reversed"}, {"text": "cumbersome", "why": "Means bulky and awkward; the passage stresses how unnoticeable the sensors are, not how heavy or unwieldy.", "tag": "unsupported"}, {"text": "ornamental", "why": "Means decorative and meant to be seen; the sensors were concealed rather than displayed for effect.", "tag": "reversed"}], "answer": 0},
{"id": "vq-hd-unoriginal", "wordId": "hd-unoriginal", "skill": "words-in-context", "stem": "Reviewers admired the young composer's polished technique but ultimately judged her debut symphony ______: nearly every melody plainly echoed a well-known predecessor, and even sympathetic critics struggled to point to a single genuinely fresh idea in the score.", "choices": [{"text": "discordant", "why": "Means clashing or harsh in sound; the criticism concerns a lack of new ideas, not the work's harmony.", "tag": "unsupported"}, {"text": "unoriginal", "why": "Melodies that 'echoed a well-known predecessor' with no 'genuinely fresh idea' mark the work as lacking originality."}, {"text": "ambitious", "why": "Means grand in aim or scale; the passage faults the symphony's derivativeness, not its scope of aspiration.", "tag": "true-but-irrelevant"}, {"text": "flawless", "why": "Means without defect; this is broadly positive and ignores the specific complaint that the music borrowed too heavily.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-hd-unpretentious", "wordId": "hd-unpretentious", "skill": "words-in-context", "stem": "For all its Michelin stars, the little bistro remained refreshingly ______: paper napkins, a menu written by hand each morning, and a jumble of mismatched chairs signaled that the kitchen cared far more about the food than about impressing anyone.", "choices": [{"text": "opulent", "why": "Means lavish and luxurious; paper napkins and mismatched chairs are the opposite of showy extravagance.", "tag": "reversed"}, {"text": "exclusive", "why": "Means restricted to a select few; the details convey modesty, not high-status selectivity.", "tag": "unsupported"}, {"text": "austere", "why": "Means sternly bare or self-denying; the tone is warm and casual, not harshly spartan, so it adds a severity the passage does not support.", "tag": "too-specific"}, {"text": "unpretentious", "why": "Plain napkins, a handwritten menu, and mismatched chairs that show the kitchen 'cared far more about the food than about impressing anyone' define a modest, unshowy establishment."}], "answer": 3},
{"id": "vq-hd-variable", "wordId": "hd-variable", "skill": "words-in-context", "stem": "Unlike the Sun, whose luminosity holds nearly steady from year to year, the red supergiant Betelgeuse is strikingly ______ : over a roughly 400-day cycle, the star dims to a fraction of its peak brightness and then recovers, a rhythm astronomers have tracked for decades.", "choices": [{"text": "variable", "why": "The contrast with the Sun's steady output, plus the described cycle of dimming and recovering, requires a word meaning subject to change."}, {"text": "uniform", "why": "Reversed: uniform means constant and unchanging — that describes the Sun in the contrast, not a star that dims and rebrightens.", "tag": "reversed"}, {"text": "erratic", "why": "Adds irregularity the passage rules out: erratic means changing unpredictably, but the star follows a regular 400-day rhythm.", "tag": "too-specific"}, {"text": "imperceptible", "why": "Unsupported: imperceptible means too slight to notice; dimming 'to a fraction of its peak brightness,' tracked for decades, is plainly observable.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-hd-verisimilitude", "wordId": "hd-verisimilitude", "skill": "words-in-context", "stem": "Though every character and plot turn in the novel is invented, the author combed 1940s Chicago newspapers to reproduce the era's slang, streetcar routes, and grocery prices, lending her fiction a degree of ______ that convinces readers they are moving through a real, remembered city.", "choices": [{"text": "pathos", "why": "Unsupported: pathos is a quality that evokes pity or sadness; the passage concerns seeming real, not stirring emotion.", "tag": "unsupported"}, {"text": "verisimilitude", "why": "The clue is the effect on readers: period details make an admittedly invented story 'convince readers they are moving through a real city' — the appearance of reality in fiction."}, {"text": "accuracy", "why": "True but beside the point: the period details are factually correct, yet since the story itself is wholly invented, what they lend the fiction is the feel of truth, not factual correctness.", "tag": "true-but-irrelevant"}, {"text": "whimsy", "why": "Unsupported: whimsy means playful fancifulness; painstakingly reproduced streetcar routes and prices aim at realism, not playfulness.", "tag": "unsupported"}], "answer": 1}
);
